import React from 'react'
import { useApp } from '../state/AppContext'
import type { SafetyEvent, LifecycleStage } from '../data/types'
import { fmtAgo } from '../utils/format'

const STAGES: { id: LifecycleStage; label: string }[] = [
    { id: 'detected', label: 'Object Detected' },
    { id: 'classified', label: 'Event Classified' },
    { id: 'risk_evaluated', label: 'Risk Evaluated' },
    { id: 'alert_generated', label: 'Alert Generated' },
    { id: 'human_review', label: 'Human Review' },
    { id: 'action_assigned', label: 'Action Assigned' },
    { id: 'resolution', label: 'Resolution' },
    { id: 'kpi_updated', label: 'KPI Updated' },
]

export default function Lifecycle({ event }: { event: SafetyEvent }) {
    const { now } = useApp()
    let current = STAGES.findIndex((s) => s.id === event.stage)
    if (current < 0) current = 0
    const resolved = event.status === 'resolved' || event.status === 'false_positive'
    const doneThrough = resolved ? STAGES.length - 1 : current

    return (
        <div>
            <div className="vicc-section-title">Lifecycle</div>
            <div className="vicc-flow">
                {STAGES.map((s, i) => {
                    const isCurrent = i === current && !resolved
                    const isDone = i < doneThrough || (resolved && i <= doneThrough)
                    return (
                        <React.Fragment key={s.id}>
                            <span className={`vicc-flow__step ${isDone ? 'is-done' : ''} ${isCurrent ? 'is-current' : ''}`}>
                                <span className="n">{i + 1}</span>
                                {s.label}
                            </span>
                            {i < STAGES.length - 1 ? <span className="vicc-flow__arr">›</span> : null}
                        </React.Fragment>
                    )
                })}
            </div>

            <div className="vicc-section-title" style={{ marginTop: 14 }}>Activity Audit</div>
            <div className="vicc-timeline">
                {event.audit
                    .slice()
                    .reverse()
                    .map((a, i) => (
                        <div className="vicc-timeline__item" key={i}>
                            <div className="vicc-timeline__action">{a.action}</div>
                            <div className="vicc-timeline__detail">
                                {a.actor} · {a.detail}
                            </div>
                            <div className="vicc-timeline__time">{fmtAgo(a.at, now)}</div>
                        </div>
                    ))}
            </div>
        </div>
    )
}
