import React from 'react'
import type { Environment } from '../data/types'

// Four tightly-framed, non-overlapping anchor rectangles (% of the 16:9 frame),
// each positioned ON a drawn figure so bounding boxes never float or collide —
// mirroring the clean reference layout (3 workers + 1 forklift).
export interface Anchor {
    x: number
    y: number
    w: number
    h: number
    cats: string[] // preferred detection categories for this object
}

export const SCENE_ANCHORS: Anchor[] = [
    { x: 5.5, y: 44, w: 12, h: 32, cats: ['person', 'vest'] },
    { x: 26.5, y: 44, w: 12, h: 32, cats: ['helmet', 'person'] }, // no-helmet worker (severity → red)
    { x: 47.5, y: 44, w: 12, h: 32, cats: ['person', 'vest'] },
    { x: 67, y: 48, w: 22, h: 31, cats: ['forklift', 'vehicle', 'truck'] },
]

const SKY: Record<Environment, [string, string]> = {
    refinery: ['#17324c', '#243f30'],
    pipeline: ['#15293c', '#203d4f'],
    tankfarm: ['#182b3e', '#24415a'],
    warehouse: ['#17222f', '#1d3346'],
    construction: ['#1c2a3a', '#2a3a2a'],
    restricted: ['#201a2c', '#1a2a3a'],
}

// A worker figure centred on `cx` (viewBox units). Head ≈ y26, feet ≈ y42.
function Worker({ cx, hiVis, helmet }: { cx: number; hiVis: string; helmet: boolean }) {
    return (
        <g>
            {helmet ? <path d={`M${cx - 1.7} 26.2 a1.7 1.7 0 0 1 3.4 0 Z`} fill="#ffd36b" /> : null}
            <circle cx={cx} cy={27.8} r={1.7} fill="#e7cf9a" />
            <rect x={cx - 2} y={29.6} width={4} height={7.2} rx={1.1} fill={hiVis} opacity={0.92} />
            <rect x={cx - 1.7} y={30.8} width={3.4} height={1.9} fill="rgba(255,255,255,0.4)" />
            <rect x={cx - 1.7} y={36.6} width={1.4} height={5.4} fill="#223a49" />
            <rect x={cx + 0.3} y={36.6} width={1.4} height={5.4} fill="#223a49" />
        </g>
    )
}

// Cinematic, stylised industrial plant scene drawn entirely in SVG (UI Pages
// cannot bundle real video/images). Objects align under SCENE_ANCHORS.
export default function IndustrialScene({ env }: { env: Environment }) {
    const [a, b] = SKY[env] || SKY.refinery
    return (
        <svg className="vicc-scene" viewBox="0 0 100 56.25" preserveAspectRatio="none" aria-hidden="true">
            <defs>
                <linearGradient id="vc-sky" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="0" stopColor={a} />
                    <stop offset="1" stopColor={b} />
                </linearGradient>
                <linearGradient id="vc-ground" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="0" stopColor="#13202b" />
                    <stop offset="1" stopColor="#0a131b" />
                </linearGradient>
                <radialGradient id="vc-sun" cx="0.72" cy="0.3" r="0.55">
                    <stop offset="0" stopColor="rgba(255,190,85,0.38)" />
                    <stop offset="1" stopColor="rgba(255,190,85,0)" />
                </radialGradient>
                <linearGradient id="vc-flame" x1="0" y1="1" x2="0" y2="0">
                    <stop offset="0" stopColor="#ffbe55" />
                    <stop offset="1" stopColor="#ff6673" />
                </linearGradient>
            </defs>

            {/* sky + sun glow + ground */}
            <rect x="0" y="0" width="100" height="44" fill="url(#vc-sky)" />
            <rect x="0" y="0" width="100" height="44" fill="url(#vc-sun)" />
            <rect x="0" y="42" width="100" height="14.25" fill="url(#vc-ground)" />
            <line x1="0" y1="42" x2="100" y2="42" stroke="rgba(56,217,230,0.22)" strokeWidth="0.2" />

            {/* refinery skyline: towers, tanks, columns, stacks, pipe rack */}
            <g opacity="0.82">
                <g fill="#1d3647" stroke="rgba(56,217,230,0.13)" strokeWidth="0.15">
                    <rect x="2" y="23" width="7" height="19" rx="0.8" />
                    <rect x="9.5" y="28" width="4" height="14" rx="0.6" />
                    <rect x="19" y="19" width="4.5" height="23" rx="0.8" />
                    <rect x="24" y="25" width="3" height="17" />
                    <rect x="73" y="21" width="5" height="21" rx="0.8" />
                    <rect x="79" y="27" width="3.5" height="15" />
                    <rect x="88" y="17" width="5.5" height="25" rx="0.8" />
                    <rect x="94" y="24" width="4" height="18" rx="0.6" />
                </g>
                <g>
                    <rect x="38" y="16" width="5" height="26" rx="1.2" fill="#243f52" stroke="rgba(56,217,230,0.18)" strokeWidth="0.15" />
                    {[20, 24, 28, 32, 36].map((y) => <line key={y} x1="38" y1={y} x2="43" y2={y} stroke="rgba(56,217,230,0.2)" strokeWidth="0.15" />)}
                </g>
                <g>
                    <rect x="61" y="15" width="1.3" height="27" fill="#33505f" />
                    <path d="M61.6 16 C 59.9 12.6, 63.6 11.8, 62.4 8.4 C 64.8 10.8, 63.7 14.4, 61.6 16 Z" fill="url(#vc-flame)" />
                    <g fill="rgba(170,188,198,0.22)">
                        <ellipse cx="60" cy="10" rx="2.3" ry="1.1" />
                        <ellipse cx="57.6" cy="12.2" rx="3" ry="1.5" />
                    </g>
                </g>
                <g stroke="#2b4453" strokeWidth="0.45" opacity="0.8">
                    <line x1="0" y1="38.5" x2="100" y2="38.5" />
                    <line x1="0" y1="40" x2="100" y2="40" />
                    {[8, 18, 30, 52, 70, 84, 96].map((x) => <line key={x} x1={x} y1="37.5" x2={x} y2="42" />)}
                </g>
            </g>

            {/* ground lane marking */}
            <g stroke="rgba(166,230,110,0.2)" strokeWidth="0.3" strokeDasharray="1.6 1.6">
                <line x1="0" y1="50" x2="100" y2="47.5" />
            </g>

            {/* foreground figures — centred under the 4 anchors */}
            <Worker cx={11.5} hiVis="#ff7a33" helmet />
            <Worker cx={32.5} hiVis="#ff5a66" helmet={false} />
            <Worker cx={53.5} hiVis="#38d9e6" helmet />

            {/* forklift (centre ≈ x78) */}
            <g>
                <rect x="71" y="34" width="11" height="7.6" rx="0.9" fill="#d8ad3f" />
                <rect x="73.6" y="29.6" width="5" height="4.4" rx="0.6" fill="#b88f2c" />
                <rect x="81.4" y="28" width="0.9" height="13.6" fill="#5a6a72" />
                <path d="M82.3 41.2 h4.6" stroke="#5a6a72" strokeWidth="0.7" />
                <path d="M82.3 38.6 h4.6" stroke="#5a6a72" strokeWidth="0.5" opacity="0.6" />
                <circle cx="74" cy="42" r="1.9" fill="#10202a" stroke="#4a6b7a" strokeWidth="0.3" />
                <circle cx="80" cy="42" r="1.9" fill="#10202a" stroke="#4a6b7a" strokeWidth="0.3" />
            </g>
        </svg>
    )
}
