// Deterministic 26 cameras spread across sites/zones/environments.
const CAM_ENV: Record<string, Environment> = {
    'ZN-PROC': 'refinery',
    'ZN-PUMP': 'pipeline',
    'ZN-TANK': 'tankfarm',
    'ZN-LOAD': 'warehouse',
    'ZN-CONS': 'construction',
    'ZN-REST': 'restricted',
}

const CAM_ASSIGN: Array<{ zone: string }> = [
    { zone: 'ZN-PROC' }, { zone: 'ZN-PROC' }, { zone: 'ZN-PROC' }, { zone: 'ZN-PROC' }, { zone: 'ZN-PROC' },
    { zone: 'ZN-PUMP' }, { zone: 'ZN-PUMP' }, { zone: 'ZN-PUMP' }, { zone: 'ZN-PUMP' },
    { zone: 'ZN-TANK' }, { zone: 'ZN-TANK' }, { zone: 'ZN-TANK' }, { zone: 'ZN-TANK' }, { zone: 'ZN-TANK' },
    { zone: 'ZN-LOAD' }, { zone: 'ZN-LOAD' }, { zone: 'ZN-LOAD' }, { zone: 'ZN-LOAD' }, { zone: 'ZN-LOAD' },
    { zone: 'ZN-CONS' }, { zone: 'ZN-CONS' }, { zone: 'ZN-CONS' }, { zone: 'ZN-CONS' },
    { zone: 'ZN-REST' }, { zone: 'ZN-REST' }, { zone: 'ZN-REST' },
]

// Offline / degraded cameras -> 24 online of 26.
const OFFLINE = new Set(['CAM-09'])
const DEGRADED = new Set(['CAM-18'])

function hash(n: number): number {
    const x = Math.sin(n * 999.37) * 10000
    return x - Math.floor(x)
}

export const CAMERAS: Camera[] = CAM_ASSIGN.map((a, i) => {
    const num = i + 1
    const id = `CAM-${String(num).padStart(2, '0')}`
    const zone = ZONES.find((z) => z.id === a.zone)!
    const status = OFFLINE.has(id) ? 'offline' : DEGRADED.has(id) ? 'degraded' : 'online'
    return {
        id,
        name: `${zone.name} ${String(num).padStart(2, '0')}`,
        siteId: zone.siteId,
        zoneId: zone.id,
        environment: CAM_ENV[zone.id],
        status,
        x: 6 + hash(num) * 88,
        y: 8 + hash(num + 100) * 84,
        angle: hash(num + 7) * 360,
        distance: 0.25 + hash(num + 13) * 0.68,
    }
})

export const CAMERA_MAP: Record<string, Camera> = Object.fromEntries(CAMERAS.map((c) => [c.id, c]))
export const SITE_MAP: Record<string, Site> = Object.fromEntries(SITES.map((s) => [s.id, s]))
export const ZONE_MAP: Record<string, Zone> = Object.fromEntries(ZONES.map((z) => [z.id, z]))

