import React, { useMemo } from 'react'
import { useApp } from '../state/AppContext'
import Radar, { radarMatch } from '../components/Radar'
import DetectionDetail from '../components/DetectionDetail'
import Lifecycle from '../components/Lifecycle'
import { CATEGORY_MAP } from '../data/catalog'
import type { Detection } from '../data/types'
import { fmtTime, pct, severityLabel } from '../utils/format'

export default function RadarTab() {
    const { filteredDetections, radarFilter, selectedDetectionId, selectDetection, events } = useApp()

    const rows = useMemo(
        () =>
            filteredDetections
                .filter((d) => radarMatch(d, radarFilter))
                .slice(0, 50)
                .sort((a, b) => b.riskScore - a.riskScore),
        [filteredDetections, radarFilter],
    )

    const sel = filteredDetections.find((d) => d.id === selectedDetectionId)
    const ev = sel?.eventId ? events.find((e) => e.id === sel.eventId) : undefined

    return (
        <div className="vicc-row vicc-fade" style={{ alignItems: 'stretch' }}>
            <div className="vicc-panel" style={{ flex: '1 1 440px', minWidth: 340 }}>
                <div className="vicc-panel__head">
                    <div className="vicc-panel__title"><span className="vicc-panel__dot" /> AI Radar Intelligence <small>signature view</small></div>
                </div>
                <div className="vicc-panel__body">
                    <Radar size="lg" showCard={false} />
                </div>
            </div>

            <div className="vicc-stack" style={{ flex: '1 1 420px', minWidth: 320 }}>
                <div className="vicc-panel">
                    <div className="vicc-panel__head">
                        <div className="vicc-panel__title"><span className="vicc-panel__dot" /> Detected Objects <small>{rows.length} · by risk</small></div>
                    </div>
                    <div className="vicc-panel__body vicc-scroll" style={{ maxHeight: 280 }}>
                        <table className="vicc-table">
                            <thead>
                                <tr><th>Object</th><th>Camera</th><th>Conf</th><th>Severity</th><th>Risk</th><th>Seen</th></tr>
                            </thead>
                            <tbody>
                                {rows.map((d: Detection) => (
                                    <tr key={d.id} className={d.id === selectedDetectionId ? 'is-selected' : ''} onClick={() => selectDetection(d.id)}>
                                        <td>{CATEGORY_MAP[d.category]?.label}</td>
                                        <td>{d.cameraId}</td>
                                        <td className="num">{pct(d.confidence)}</td>
                                        <td><span className={`vicc-chip is-${d.severity}`}><span className="d" /> {severityLabel(d.severity)}</span></td>
                                        <td className="num">{d.riskScore}</td>
                                        <td className="num">{fmtTime(d.timestamp)}</td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>

                <DetectionDetail />

                {ev ? (
                    <div className="vicc-panel">
                        <div className="vicc-panel__head">
                            <div className="vicc-panel__title"><span className="vicc-panel__dot" /> Event Timeline <small>{ev.id}</small></div>
                        </div>
                        <div className="vicc-panel__body">
                            <Lifecycle event={ev} />
                        </div>
                    </div>
                ) : null}
            </div>
        </div>
    )
}
