import React, { useMemo, useState } from 'react'
import { useApp } from '../state/AppContext'
import EventActions from '../components/EventActions'
import Lifecycle from '../components/Lifecycle'
import { CAMERA_MAP, ZONE_MAP, SEVERITY_RANK } from '../data/catalog'
import type { EventStatus } from '../data/types'
import { fmtAgo, pct, severityLabel } from '../utils/format'

const STATUS_PILLS: { id: 'all' | EventStatus; label: string }[] = [
    { id: 'all', label: 'All' },
    { id: 'active', label: 'Active' },
    { id: 'acknowledged', label: 'Acknowledged' },
    { id: 'investigating', label: 'Investigating' },
    { id: 'resolved', label: 'Resolved' },
    { id: 'false_positive', label: 'False Positive' },
]
const OPEN_RANK: Record<string, number> = { active: 0, acknowledged: 1, investigating: 2, resolved: 3, false_positive: 4 }

export default function Safety() {
    const { filteredEvents, selectedEventId, selectEvent, now } = useApp()
    const [status, setStatus] = useState<'all' | EventStatus>('all')

    const scenarios = useMemo(() => filteredEvents.filter((e) => e.scenarioKey && e.scenarioKey !== 'demo'), [filteredEvents])

    const list = useMemo(() => {
        return filteredEvents
            .filter((e) => status === 'all' || e.status === status)
            .slice()
            .sort(
                (a, b) =>
                    OPEN_RANK[a.status] - OPEN_RANK[b.status] ||
                    SEVERITY_RANK[b.severity] - SEVERITY_RANK[a.severity] ||
                    b.detectedAt - a.detectedAt,
            )
    }, [filteredEvents, status])

    const sel = filteredEvents.find((e) => e.id === selectedEventId) || null
    const cam = sel ? CAMERA_MAP[sel.cameraId] : null

    return (
        <div className="vicc-row vicc-fade" style={{ alignItems: 'stretch' }}>
            <div className="vicc-stack" style={{ flex: '1 1 400px', minWidth: 320 }}>
                <div className="vicc-panel">
                    <div className="vicc-panel__head">
                        <div className="vicc-panel__title"><span className="vicc-panel__dot" /> Storytelling Scenarios</div>
                        <small style={{ color: 'var(--vc-muted)' }}>{scenarios.length}</small>
                    </div>
                    <div className="vicc-panel__body">
                        <div className="vicc-row" style={{ gap: 6 }}>
                            {scenarios.map((e) => (
                                <button
                                    key={e.id}
                                    className={`vicc-pill ${e.id === selectedEventId ? 'is-active' : ''}`}
                                    onClick={() => selectEvent(e.id)}
                                    title={e.title}
                                >
                                    {e.cameraId} · {severityLabel(e.severity)}
                                </button>
                            ))}
                        </div>
                    </div>
                </div>

                <div className="vicc-panel">
                    <div className="vicc-panel__head">
                        <div className="vicc-panel__title"><span className="vicc-panel__dot" /> Safety Events <small>{list.length}</small></div>
                    </div>
                    <div className="vicc-panel__body">
                        <div className="vicc-radar__filters" style={{ marginBottom: 10 }}>
                            {STATUS_PILLS.map((p) => (
                                <button key={p.id} className={`vicc-pill ${status === p.id ? 'is-active' : ''}`} onClick={() => setStatus(p.id)}>
                                    {p.label}
                                </button>
                            ))}
                        </div>
                        <div className="vicc-scroll" style={{ maxHeight: 440 }}>
                            {list.length === 0 ? <div className="vicc-empty">No events match the current filters.</div> : null}
                            {list.map((e) => (
                                <button
                                    key={e.id}
                                    className="vicc-insight"
                                    onClick={() => selectEvent(e.id)}
                                    style={{ display: 'block', width: '100%', textAlign: 'left', cursor: 'pointer', marginBottom: 8, borderColor: e.id === selectedEventId ? 'var(--vc-cyan)' : undefined }}
                                >
                                    <div style={{ display: 'flex', justifyContent: 'space-between', gap: 8, alignItems: 'center' }}>
                                        <span style={{ fontWeight: 800, fontSize: '0.8rem' }}>{e.title}</span>
                                        <span className={`vicc-chip is-${e.severity}`}><span className="d" /> {severityLabel(e.severity)}</span>
                                    </div>
                                    <div style={{ display: 'flex', gap: 8, marginTop: 5, fontSize: '0.7rem', color: 'var(--vc-muted)', flexWrap: 'wrap', alignItems: 'center' }}>
                                        <span className={`vicc-chip st-${e.status}`}><span className="d" /> {e.status.replace('_', ' ')}</span>
                                        <span>{e.cameraId}</span>
                                        {e.incidentNumber ? <span style={{ color: 'var(--vc-cyan)' }}>{e.incidentNumber}</span> : null}
                                        <span>{fmtAgo(e.detectedAt, now)}</span>
                                    </div>
                                </button>
                            ))}
                        </div>
                    </div>
                </div>
            </div>

            <div className="vicc-panel" style={{ flex: '1 1 460px', minWidth: 340 }}>
                {sel ? (
                    <>
                        <div className="vicc-panel__head">
                            <div className="vicc-panel__title">
                                <span className="vicc-panel__dot" style={{ background: 'var(--vc-red)', boxShadow: '0 0 10px var(--vc-red)' }} /> {sel.title}
                            </div>
                            <span className={`vicc-chip st-${sel.status}`}><span className="d" /> {sel.status.replace('_', ' ')}</span>
                        </div>
                        <div className="vicc-panel__body vicc-scroll" style={{ maxHeight: 620 }}>
                            <div className="vicc-detail" style={{ marginBottom: 12 }}>
                                <div className="vicc-detail__row"><span>Severity</span><b>{severityLabel(sel.severity)}</b></div>
                                {sel.screening ? (
                                    <div className="vicc-detail__row"><span>Screening score</span><b style={{ color: 'var(--vc-amber)' }}>{Math.round((sel.screeningScore || 0) * 100)}% rel.</b></div>
                                ) : (
                                    <div className="vicc-detail__row"><span>Confidence</span><b>{pct(sel.confidence)}</b></div>
                                )}
                                <div className="vicc-detail__row"><span>Risk Score</span><b>{sel.riskScore} / 100</b></div>
                                <div className="vicc-detail__row"><span>Camera / Zone</span><b>{cam?.id} · {ZONE_MAP[sel.zoneId]?.name}</b></div>
                                <div className="vicc-detail__row"><span>Owner</span><b>{sel.owner || 'Unassigned'}</b></div>
                                <div className="vicc-detail__row"><span>Source</span><b>{sel.source === 'cv' ? 'Connected CV feed' : 'Simulation'}</b></div>
                                {sel.incidentNumber ? <div className="vicc-detail__row"><span>Incident</span><b style={{ color: 'var(--vc-cyan)' }}>{sel.incidentNumber}</b></div> : null}
                            </div>

                            {sel.screening ? (
                                <p className="vicc-note" style={{ margin: '0 0 12px', color: 'var(--vc-amber)' }}>
                                    ⚠ Experimental fire/smoke screening (zero-shot). The score is a relative similarity, <b>not</b> a calibrated fire-detection confidence. Visually verify before confirming an incident.
                                </p>
                            ) : null}
                            <div className="vicc-section-title">Recommended Response</div>
                            <p style={{ fontSize: '0.82rem', margin: '0 0 12px', color: 'var(--vc-white)' }}>{sel.recommended}</p>

                            <EventActions event={sel} />
                            <div style={{ marginTop: 14 }}>
                                <Lifecycle event={sel} />
                            </div>
                        </div>
                    </>
                ) : (
                    <div className="vicc-panel__body"><div className="vicc-empty">Select a safety event to review details, lifecycle, and response actions.</div></div>
                )}
            </div>
        </div>
    )
}
