import React, { useEffect, useMemo, useRef } from 'react'
import { useApp } from '../state/AppContext'
import { CATEGORY_MAP, PALETTE, SEVERITY_COLOR } from '../data/catalog'
import type { Detection, RadarFilter, Severity } from '../data/types'
import { polar, pct, fmtAgo, severityLabel } from '../utils/format'

const FILTERS: { id: RadarFilter; label: string }[] = [
    { id: 'all', label: 'All' },
    { id: 'safety', label: 'Safety Violations' },
    { id: 'intrusion', label: 'Restricted Intrusions' },
    { id: 'equipment', label: 'Equipment Anomalies' },
    { id: 'highrisk', label: 'High Risk' },
    { id: 'logistics', label: 'Vehicles & Logistics' },
]

const LEGEND: { label: string; color: string }[] = [
    { label: 'Person', color: CATEGORY_MAP.person.color },
    { label: 'Logistics', color: CATEGORY_MAP.vehicle.color },
    { label: 'Equipment', color: CATEGORY_MAP.pump.color },
    { label: 'Safety PPE', color: CATEGORY_MAP.helmet.color },
    { label: 'Hazard', color: CATEGORY_MAP.smoke.color },
    { label: 'Intrusion', color: CATEGORY_MAP.intrusion.color },
]

const SEV_SIZE: Record<string, number> = { low: 3, medium: 4, high: 5.2, critical: 6.5 }

export function radarMatch(d: Detection, f: RadarFilter): boolean {
    switch (f) {
        case 'safety':
            return d.category === 'helmet' || d.category === 'vest'
        case 'intrusion':
            return d.category === 'intrusion'
        case 'equipment':
            return d.category === 'pump' || d.category === 'pipeline' || d.category === 'equipment'
        case 'highrisk':
            return d.severity === 'high' || d.severity === 'critical'
        case 'logistics':
            return d.category === 'vehicle' || d.category === 'truck' || d.category === 'forklift'
        default:
            return true
    }
}

// deterministic de-cluster offset per detection id (display only — stable per blip)
function jitter(id: string): { a: number; b: number } {
    let h = 2166136261
    for (let i = 0; i < id.length; i++) {
        h ^= id.charCodeAt(i)
        h = Math.imul(h, 16777619)
    }
    const a = ((h >>> 0) % 1000) / 1000
    const b = ((h >>> 10) % 1000) / 1000
    return { a, b }
}

interface Blip { id: string; category: string; severity: Severity; angle: number; dist: number }

export default function Radar({ size = 'md', showCard = true }: { size?: 'md' | 'lg'; showCard?: boolean }) {
    const { filteredDetections, radarFilter, setRadarFilter, simRunning, selectedDetectionId, selectDetection, detections, events, now, navigate, selectEvent } = useApp()
    const canvasRef = useRef<HTMLCanvasElement>(null)

    const blips = useMemo<Blip[]>(
        () =>
            filteredDetections
                .filter((d) => radarMatch(d, radarFilter))
                .slice(0, 50)
                .map((d) => {
                    const j = jitter(d.id)
                    return {
                        id: d.id,
                        category: d.category,
                        severity: d.severity,
                        angle: (d.radar.angle + (j.a - 0.5) * 30 + 360) % 360,
                        dist: Math.max(0.12, Math.min(0.95, d.radar.distance + (j.b - 0.5) * 0.22)),
                    }
                }),
        [filteredDetections, radarFilter],
    )

    const blipsRef = useRef(blips)
    const simRef = useRef(simRunning)
    const selRef = useRef(selectedDetectionId)
    const posRef = useRef<{ id: string; x: number; y: number; r: number }[]>([])
    blipsRef.current = blips
    simRef.current = simRunning
    selRef.current = selectedDetectionId

    useEffect(() => {
        let raf = 0
        let sweep = 0
        let last = performance.now()
        const canvas = canvasRef.current
        if (!canvas) return
        const ctx = canvas.getContext('2d')
        if (!ctx) return

        const draw = (ts: number) => {
            const dt = ts - last
            last = ts
            if (simRef.current) sweep = (sweep + dt * 0.09) % 360

            const dpr = window.devicePixelRatio || 1
            const cssW = canvas.clientWidth || 300
            const cssH = canvas.clientHeight || 300
            if (canvas.width !== Math.round(cssW * dpr) || canvas.height !== Math.round(cssH * dpr)) {
                canvas.width = Math.round(cssW * dpr)
                canvas.height = Math.round(cssH * dpr)
            }
            ctx.setTransform(dpr, 0, 0, dpr, 0, 0)
            const w = cssW
            const h = cssH
            const cx = w / 2
            const cy = h / 2
            const R = Math.min(w, h) / 2 - 6

            ctx.clearRect(0, 0, w, h)
            const bg = ctx.createRadialGradient(cx, cy, 0, cx, cy, R)
            bg.addColorStop(0, 'rgba(13,36,51,0.95)')
            bg.addColorStop(1, 'rgba(6,16,25,0.98)')
            ctx.fillStyle = bg
            ctx.beginPath()
            ctx.arc(cx, cy, R, 0, Math.PI * 2)
            ctx.fill()

            ctx.strokeStyle = 'rgba(56,217,230,0.18)'
            ctx.lineWidth = 1
            for (let i = 1; i <= 4; i++) {
                ctx.beginPath()
                ctx.arc(cx, cy, (R * i) / 4, 0, Math.PI * 2)
                ctx.stroke()
            }
            ctx.beginPath()
            ctx.moveTo(cx - R, cy)
            ctx.lineTo(cx + R, cy)
            ctx.moveTo(cx, cy - R)
            ctx.lineTo(cx, cy + R)
            ctx.stroke()
            ctx.fillStyle = 'rgba(159,180,192,0.8)'
            ctx.font = '10px sans-serif'
            ctx.textAlign = 'center'
            ctx.textBaseline = 'middle'
            ctx.fillText('N', cx, cy - R + 9)
            ctx.fillText('S', cx, cy + R - 9)
            ctx.fillText('E', cx + R - 9, cy)
            ctx.fillText('W', cx - R + 9, cy)

            const TRAIL = 64
            for (let i = 0; i < TRAIL; i++) {
                const ang = sweep - i
                const p = polar(ang, 1, cx, cy, R)
                ctx.strokeStyle = `rgba(56,217,230,${(1 - i / TRAIL) * 0.16})`
                ctx.lineWidth = 1
                ctx.beginPath()
                ctx.moveTo(cx, cy)
                ctx.lineTo(p.x, p.y)
                ctx.stroke()
            }
            const lead = polar(sweep, 1, cx, cy, R)
            const lg = ctx.createLinearGradient(cx, cy, lead.x, lead.y)
            lg.addColorStop(0, 'rgba(56,217,230,0.95)')
            lg.addColorStop(1, 'rgba(166,230,110,0.9)')
            ctx.strokeStyle = lg
            ctx.lineWidth = 2
            ctx.beginPath()
            ctx.moveTo(cx, cy)
            ctx.lineTo(lead.x, lead.y)
            ctx.stroke()

            const pos: { id: string; x: number; y: number; r: number }[] = []
            for (const b of blipsRef.current) {
                const p = polar(b.angle, b.dist, cx, cy, R)
                const color = CATEGORY_MAP[b.category]?.color || SEVERITY_COLOR[b.severity]
                const base = SEV_SIZE[b.severity] || 4
                const diff = (sweep - b.angle + 360) % 360
                const passGlow = diff < 90 ? 1 - diff / 90 : 0
                const pulse = 0.5 + 0.5 * Math.sin(ts / 320 + b.angle)
                const isSel = b.id === selRef.current
                const isCrit = b.severity === 'critical'
                const r = base + passGlow * 2 + (isSel ? 2 : 0)

                ctx.beginPath()
                ctx.arc(p.x, p.y, r + 5, 0, Math.PI * 2)
                ctx.fillStyle = color + Math.round((0.12 + passGlow * 0.3 + pulse * (isCrit ? 0.16 : 0.08)) * 255).toString(16).padStart(2, '0')
                ctx.fill()

                ctx.beginPath()
                ctx.arc(p.x, p.y, r, 0, Math.PI * 2)
                ctx.fillStyle = color
                ctx.globalAlpha = 0.75 + passGlow * 0.25
                ctx.fill()
                ctx.globalAlpha = 1

                if (isCrit) {
                    ctx.strokeStyle = PALETTE.red
                    ctx.lineWidth = 1.2
                    ctx.globalAlpha = 0.5 + pulse * 0.5
                    ctx.beginPath()
                    ctx.arc(p.x, p.y, r + 3.5, 0, Math.PI * 2)
                    ctx.stroke()
                    ctx.globalAlpha = 1
                }
                if (isSel) {
                    ctx.strokeStyle = PALETTE.white
                    ctx.lineWidth = 2
                    ctx.beginPath()
                    ctx.arc(p.x, p.y, r + 7, 0, Math.PI * 2)
                    ctx.stroke()
                }
                pos.push({ id: b.id, x: p.x, y: p.y, r: r + 7 })
            }
            posRef.current = pos

            raf = requestAnimationFrame(draw)
        }
        raf = requestAnimationFrame(draw)
        return () => cancelAnimationFrame(raf)
    }, [])

    const onClick = (e: React.MouseEvent<HTMLCanvasElement>) => {
        const canvas = canvasRef.current
        if (!canvas) return
        const rect = canvas.getBoundingClientRect()
        const mx = e.clientX - rect.left
        const my = e.clientY - rect.top
        let best: { id: string; dist: number } | null = null
        for (const b of posRef.current) {
            const d = Math.hypot(b.x - mx, b.y - my)
            if (d <= Math.max(10, b.r) && (!best || d < best.dist)) best = { id: b.id, dist: d }
        }
        if (best) selectDetection(best.id)
    }

    const sel = selectedDetectionId ? detections.find((d) => d.id === selectedDetectionId) : null
    const selEvent = sel?.eventId ? events.find((e) => e.id === sel.eventId) : null

    return (
        <div>
            <div className="vicc-radar">
                <div className="vicc-radar__wrap" style={{ maxWidth: size === 'lg' ? 560 : 420 }}>
                    <span className="vicc-radar__count">{blips.length} / 50 tracked</span>
                    <canvas ref={canvasRef} onClick={onClick} role="img" aria-label={`Radar showing ${blips.length} detections`} />
                </div>
            </div>

            {showCard && sel ? (
                <div className="vicc-blipcard vicc-fade">
                    <div className="vicc-blipcard__head">
                        <strong style={{ fontSize: '0.84rem' }}>{sel.label} · {sel.id}</strong>
                        <span className={`vicc-chip is-${sel.severity}`}><span className="d" /> {severityLabel(sel.severity)}</span>
                    </div>
                    <div className="vicc-blipcard__grid">
                        <span className="k">Category</span><b>{CATEGORY_MAP[sel.category]?.label}</b>
                        <span className="k">Confidence</span><b>{pct(sel.confidence)}</b>
                        <span className="k">Risk score</span><b>{sel.riskScore} / 100</b>
                        <span className="k">Camera</span><b>{sel.cameraId}</b>
                        <span className="k">Last seen</span><b>{fmtAgo(sel.timestamp, now)}</b>
                        <span className="k">Event</span><b>{sel.eventId || '—'}</b>
                    </div>
                    <button
                        className="vicc-btn vicc-btn--primary vicc-btn--sm"
                        style={{ marginTop: 10 }}
                        onClick={() => {
                            if (selEvent) {
                                selectEvent(selEvent.id)
                                navigate('safety')
                            } else {
                                navigate('monitoring')
                            }
                        }}
                    >
                        View details
                    </button>
                </div>
            ) : null}

            <div className="vicc-radar__group">
                <div className="vicc-radar__cap">Filters</div>
                <div className="vicc-radar__filters" style={{ justifyContent: 'center' }}>
                    {FILTERS.map((f) => (
                        <button
                            key={f.id}
                            className={`vicc-pill ${radarFilter === f.id ? 'is-active' : ''}`}
                            onClick={() => setRadarFilter(f.id)}
                        >
                            {f.label}
                        </button>
                    ))}
                </div>
            </div>

            <div className="vicc-radar__divider" />

            <div className="vicc-radar__group">
                <div className="vicc-radar__cap">Legend</div>
                <div className="vicc-radar__legend">
                    {LEGEND.map((l) => (
                        <span key={l.label} className="vicc-legend-item">
                            <span className="d" style={{ color: l.color, background: l.color }} /> {l.label}
                        </span>
                    ))}
                </div>
            </div>

            <p className="vicc-note" style={{ textAlign: 'center', marginTop: 8 }}>
                Simulated spatial detection field — bearing/distance are illustrative, not physical measurements.
            </p>
        </div>
    )
}
