import type { Dataset, Detection, SafetyEvent, Severity, CategoryId } from './types'
import { CATEGORIES, ZONES, ZONE_MAP, CAMERAS, SEVERITY_RANK } from './catalog'

export interface Filters {
    siteId: string // 'all' | SITE id
    category: string // 'all' | CategoryId
    severity: string // 'all' | Severity
    window: '1h' | '6h' | '24h'
}

export const WINDOW_MS: Record<Filters['window'], number> = {
    '1h': 3600_000,
    '6h': 6 * 3600_000,
    '24h': 24 * 3600_000,
}

const OPEN_STATUSES = new Set(['active', 'acknowledged', 'investigating'])

export function filterDetections(ds: Dataset, f: Filters, now: number): Detection[] {
    const cutoff = now - WINDOW_MS[f.window]
    return ds.detections.filter(
        (d) =>
            d.timestamp >= cutoff &&
            (f.siteId === 'all' || d.siteId === f.siteId) &&
            (f.category === 'all' || d.category === f.category) &&
            (f.severity === 'all' || d.severity === f.severity),
    )
}

export function filterEvents(ds: Dataset, events: SafetyEvent[], f: Filters): SafetyEvent[] {
    return events.filter(
        (e) =>
            (f.siteId === 'all' || e.siteId === f.siteId) &&
            (f.category === 'all' || e.category === f.category) &&
            (f.severity === 'all' || e.severity === f.severity),
    )
}

const round1 = (n: number) => Math.round(n * 10) / 10

export interface Kpi {
    key: string
    label: string
    value: string
    sub?: string
    trend: number // percent vs previous period (can be negative)
    goodWhenUp: boolean
    tone: 'cyan' | 'vibrant' | 'amber' | 'red' | 'green'
    drill: { tab: string; category?: string; severity?: string }
}

export function computeKpis(
    ds: Dataset,
    events: SafetyEvent[],
    f: Filters,
    now: number,
): Kpi[] {
    const dets = filterDetections(ds, f, now)
    const evs = filterEvents(ds, events, f)
    const cams = CAMERAS.filter((c) => f.siteId === 'all' || c.siteId === f.siteId)
    const online = cams.filter((c) => c.status === 'online').length
    const tracked = dets.filter((d) => d.tracked).length
    const critical = evs.filter((e) => e.severity === 'critical' && OPEN_STATUSES.has(e.status)).length
    const violations = evs.filter(
        (e) => ['helmet', 'vest', 'intrusion', 'forklift'].includes(e.category) && OPEN_STATUSES.has(e.status),
    ).length
    const compliance = round1(Math.max(80, 100 - violations * 0.6))
    const avgConf = dets.length ? round1((dets.reduce((s, d) => s + d.confidence, 0) / dets.length) * 100) : 0
    const openEvents = evs.filter((e) => OPEN_STATUSES.has(e.status))
    const risk = openEvents.length
        ? Math.round(openEvents.reduce((s, e) => s + e.riskScore, 0) / openEvents.length)
        : 0
    const resolved = evs.filter((e) => e.status === 'resolved').length

    return [
        { key: 'cameras', label: 'Active Cameras', value: `${online} / ${cams.length}`, trend: 0.8, goodWhenUp: true, tone: 'vibrant', drill: { tab: 'analytics' } },
        { key: 'objects', label: 'Objects Detected', value: dets.length.toLocaleString(), sub: `last ${f.window}`, trend: 6.4, goodWhenUp: true, tone: 'cyan', drill: { tab: 'monitoring' } },
        { key: 'tracked', label: 'Active Tracked Objects', value: String(tracked), trend: 3.1, goodWhenUp: true, tone: 'cyan', drill: { tab: 'radar' } },
        { key: 'critical', label: 'Critical Alerts', value: String(critical), trend: critical > 4 ? 12 : -8, goodWhenUp: false, tone: 'red', drill: { tab: 'safety', severity: 'critical' } },
        { key: 'compliance', label: 'Safety Compliance', value: `${compliance}%`, trend: 1.2, goodWhenUp: true, tone: 'green', drill: { tab: 'analytics' } },
        { key: 'confidence', label: 'AI Detection Confidence', value: `${avgConf}%`, trend: 0.5, goodWhenUp: true, tone: 'cyan', drill: { tab: 'monitoring' } },
        { key: 'risk', label: 'Operational Risk Score', value: `${risk} / 100`, trend: risk > 60 ? 4.5 : -3.2, goodWhenUp: false, tone: risk > 66 ? 'red' : 'amber', drill: { tab: 'safety' } },
        { key: 'resolved', label: 'Incidents Resolved Today', value: String(resolved), trend: 9, goodWhenUp: true, tone: 'vibrant', drill: { tab: 'safety' } },
    ]
}

// ---- Chart aggregations (respond to filters) ----

export function detectionsOverTime(dets: Detection[], now: number, buckets?: number): { t: number; count: number }[] {
    const n = buckets && buckets > 0 ? buckets : 24
    const span = 24 * 3600_000
    const start = (Number.isFinite(now) ? now : Date.now()) - span
    const size = span / n
    const out: { t: number; count: number }[] = []
    for (let i = 0; i < n; i++) out.push({ t: start + i * size, count: 0 })
    dets.forEach((d) => {
        const raw = Math.floor((d.timestamp - start) / size)
        const idx = Math.min(n - 1, Math.max(0, Number.isFinite(raw) ? raw : 0))
        const bucket = out[idx]
        if (bucket) bucket.count++
    })
    return out
}

export function categoryCounts(dets: Detection[]): { id: CategoryId; label: string; color: string; count: number }[] {
    return CATEGORIES.map((c) => ({
        id: c.id,
        label: c.label,
        color: c.color,
        count: dets.filter((d) => d.category === c.id).length,
    })).filter((x) => x.count > 0)
}

export function violationsByZone(events: SafetyEvent[]): { zone: string; label: string; count: number }[] {
    return ZONES.map((z) => ({
        zone: z.id,
        label: z.name,
        count: events.filter((e) => e.zoneId === z.id && ['helmet', 'vest', 'intrusion', 'forklift'].includes(e.category)).length,
    })).sort((a, b) => b.count - a.count)
}

export function severityDistribution(events: SafetyEvent[]): Record<Severity, number> {
    const out: Record<Severity, number> = { low: 0, medium: 0, high: 0, critical: 0 }
    events.forEach((e) => (out[e.severity] += 1))
    return out
}

export function topRiskZones(events: SafetyEvent[]): { label: string; score: number }[] {
    const map: Record<string, { sum: number; n: number }> = {}
    events.forEach((e) => {
        map[e.zoneId] = map[e.zoneId] || { sum: 0, n: 0 }
        map[e.zoneId].sum += e.riskScore
        map[e.zoneId].n += 1
    })
    return Object.entries(map)
        .map(([z, v]) => ({ label: ZONE_MAP[z]?.name || z, score: Math.round(v.sum / Math.max(1, v.n)) }))
        .sort((a, b) => b.score - a.score)
        .slice(0, 5)
}

export function confidenceHistogram(dets: Detection[]): { bucket: string; count: number }[] {
    const edges = [0.8, 0.85, 0.9, 0.95, 1.001]
    const labels = ['80–85%', '85–90%', '90–95%', '95–100%']
    const counts = [0, 0, 0, 0]
    dets.forEach((d) => {
        for (let i = 0; i < edges.length - 1; i++) {
            if (d.confidence >= edges[i] && d.confidence < edges[i + 1]) {
                counts[i]++
                break
            }
        }
    })
    return labels.map((bucket, i) => ({ bucket, count: counts[i] }))
}

export function repeatViolations(events: SafetyEvent[]): { label: string; count: number; color: string }[] {
    return CATEGORIES.filter((c) => ['helmet', 'vest', 'intrusion', 'forklift', 'smoke'].includes(c.id))
        .map((c) => ({
            label: c.label,
            color: c.color,
            count: events.filter((e) => e.category === c.id).length,
        }))
        .filter((x) => x.count > 0)
        .sort((a, b) => b.count - a.count)
}

export const SEVERITIES: Severity[] = ['low', 'medium', 'high', 'critical']
