import React from 'react'
import { useApp } from '../state/AppContext'
import type { TabId } from '../state/AppContext'

const LABELS: Record<TabId, string> = {
    overview: 'Overview',
    monitoring: 'Vision Monitoring',
    radar: 'Radar Intelligence',
    safety: 'Safety & Incidents',
    analytics: 'Vision Analytics',
}

const ORDER: TabId[] = ['overview', 'monitoring', 'radar', 'safety', 'analytics']
const OPEN = new Set(['active', 'acknowledged', 'investigating'])

export default function TabNav() {
    const { tab, navigate, events } = useApp()
    const openCritical = events.filter((e) => e.severity === 'critical' && OPEN.has(e.status)).length

    return (
        <nav className="vicc-tabs" role="tablist" aria-label="Command center sections">
            {ORDER.map((id) => (
                <button
                    key={id}
                    role="tab"
                    aria-selected={tab === id}
                    className={`vicc-tab ${tab === id ? 'is-active' : ''}`}
                    onClick={() => navigate(id)}
                >
                    {LABELS[id]}
                    {id === 'safety' && openCritical > 0 ? <span className="vicc-tab__badge">{openCritical}</span> : null}
                </button>
            ))}
        </nav>
    )
}
