import React from 'react'

export interface BarItem {
    label: string
    value: number
    color?: string
}
interface Props {
    items: BarItem[]
    accent?: string
    onBar?: (index: number) => void
    ranked?: boolean
}

/** Horizontal bar chart (rows). */
export default function Bars({ items, accent = '#38D9E6', onBar, ranked }: Props) {
    const max = Math.max(1, ...items.map((i) => i.value))
    return (
        <div className="vicc-chart" style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
            {items.length === 0 ? <div className="vicc-empty">No data for current filters.</div> : null}
            {items.map((it, i) => (
                <button
                    key={i}
                    onClick={onBar ? () => onBar(i) : undefined}
                    style={{
                        display: 'grid',
                        gridTemplateColumns: '120px 1fr 34px',
                        gap: 8,
                        alignItems: 'center',
                        background: 'none',
                        border: 'none',
                        padding: 0,
                        cursor: onBar ? 'pointer' : 'default',
                        fontFamily: 'inherit',
                    }}
                    title={`${it.label}: ${it.value}`}
                >
                    <span style={{ color: 'var(--vc-muted)', fontSize: '0.72rem', textAlign: 'left', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                        {ranked ? `${i + 1}. ` : ''}
                        {it.label}
                    </span>
                    <span style={{ height: 14, borderRadius: 7, background: 'rgba(255,255,255,0.06)', overflow: 'hidden' }}>
                        <span
                            style={{
                                display: 'block',
                                height: '100%',
                                width: `${(it.value / max) * 100}%`,
                                background: it.color || accent,
                                borderRadius: 7,
                                boxShadow: `0 0 10px ${it.color || accent}66`,
                                transition: 'width 500ms ease',
                            }}
                        />
                    </span>
                    <span style={{ color: 'var(--vc-white)', fontSize: '0.74rem', fontWeight: 800, textAlign: 'right' }}>{it.value}</span>
                </button>
            ))}
        </div>
    )
}
