import React, { useMemo, useState } from 'react'
import { useApp } from '../state/AppContext'
import { SITES, CAMERAS, CATEGORY_MAP } from '../data/catalog'
import { fmtClock } from '../utils/format'
import { LogoMark, SearchIcon, BellIcon } from './Icons'

const OPEN = new Set(['active', 'acknowledged', 'investigating'])

export default function Header() {
    const {
        filters,
        setFilter,
        selectedCameraId,
        selectCamera,
        simRunning,
        now,
        events,
        detections,
        navigate,
        selectDetection,
        selectEvent,
    } = useApp()
    const [q, setQ] = useState('')
    const [open, setOpen] = useState(false)

    const openCritical = events.filter((e) => e.severity === 'critical' && OPEN.has(e.status)).length
    const health = openCritical >= 3 ? 'bad' : openCritical >= 1 ? 'warn' : 'good'
    const healthLabel = health === 'bad' ? 'Degraded' : health === 'warn' ? 'Elevated' : 'Nominal'

    const cams = useMemo(() => {
        const list = CAMERAS.filter((c) => filters.siteId === 'all' || c.siteId === filters.siteId)
        if (!list.some((c) => c.id === selectedCameraId)) {
            const sel = CAMERAS.find((c) => c.id === selectedCameraId)
            if (sel) return [sel, ...list]
        }
        return list
    }, [filters.siteId, selectedCameraId])

    const results = useMemo(() => {
        const term = q.trim().toLowerCase()
        if (!term) return []
        const dets = detections
            .filter(
                (d) =>
                    d.id.toLowerCase().includes(term) ||
                    d.cameraId.toLowerCase().includes(term) ||
                    (CATEGORY_MAP[d.category]?.label || d.category).toLowerCase().includes(term),
            )
            .slice(0, 6)
        return dets
    }, [q, detections])

    return (
        <header className="vicc-header">
            <div className="vicc-logo">
                <span className="vicc-logo__mark">
                    <LogoMark />
                </span>
                <span>
                    Vision Intelligence
                    <span className="vicc-logo__sub" style={{ display: 'block' }}>
                        Command Center
                    </span>
                </span>
            </div>

            <span className={`vicc-badge ${simRunning ? 'is-live' : ''}`} title="All data is simulated for demo purposes">
                <span className="vicc-badge__dot" style={simRunning ? undefined : { animation: 'none' }} />
                Simulation
                <span style={{ fontWeight: 600, opacity: 0.85 }}>· {simRunning ? 'Live Sim' : 'Paused'}</span>
            </span>

            <div className="vicc-header__spacer" />

            <div className="vicc-header__group">
                <label className="vicc-field">
                    <span className="vicc-field__label">Site</span>
                    <select
                        className="vicc-select"
                        value={filters.siteId}
                        onChange={(e) => setFilter({ siteId: e.target.value })}
                        aria-label="Site filter"
                    >
                        <option value="all">All Sites</option>
                        {SITES.map((s) => (
                            <option key={s.id} value={s.id}>
                                {s.code} — {s.name}
                            </option>
                        ))}
                    </select>
                </label>

                <label className="vicc-field">
                    <span className="vicc-field__label">Camera</span>
                    <select
                        className="vicc-select"
                        value={selectedCameraId}
                        onChange={(e) => selectCamera(e.target.value)}
                        aria-label="Camera selector"
                    >
                        {cams.map((c) => (
                            <option key={c.id} value={c.id}>
                                {c.id} · {c.name}
                            </option>
                        ))}
                    </select>
                </label>

                <div className="vicc-field" style={{ position: 'relative' }}>
                    <span className="vicc-field__label">Search</span>
                    <div style={{ position: 'relative', display: 'flex', alignItems: 'center' }}>
                        <span style={{ position: 'absolute', left: 9, color: 'var(--vc-muted-2)', display: 'grid' }}>
                            <SearchIcon size={14} />
                        </span>
                        <input
                            className="vicc-input"
                            style={{ paddingLeft: 28, minWidth: 180 }}
                            placeholder="id / camera / category"
                            value={q}
                            onChange={(e) => {
                                setQ(e.target.value)
                                setOpen(true)
                            }}
                            onFocus={() => setOpen(true)}
                            onBlur={() => window.setTimeout(() => setOpen(false), 150)}
                            aria-label="Global search"
                        />
                    </div>
                    {open && results.length > 0 ? (
                        <div
                            className="vicc-panel vicc-fade"
                            style={{ position: 'absolute', top: '100%', right: 0, marginTop: 6, width: 280, zIndex: 50, padding: 6 }}
                        >
                            {results.map((d) => (
                                <button
                                    key={d.id}
                                    className="vicc-btn vicc-btn--ghost vicc-btn--sm"
                                    style={{ width: '100%', justifyContent: 'space-between', marginBottom: 4 }}
                                    onMouseDown={(e) => e.preventDefault()}
                                    onClick={() => {
                                        setQ('')
                                        setOpen(false)
                                        if (d.eventId) {
                                            selectEvent(d.eventId)
                                            navigate('safety')
                                        } else {
                                            selectDetection(d.id)
                                            navigate('monitoring')
                                        }
                                    }}
                                >
                                    <span>{d.id} · {CATEGORY_MAP[d.category]?.label}</span>
                                    <span style={{ color: 'var(--vc-muted)' }}>{d.cameraId}</span>
                                </button>
                            ))}
                        </div>
                    ) : null}
                </div>

                <div className={`vicc-health is-${health}`} title={`${openCritical} open critical alert(s)`}>
                    <span className="vicc-health__dot" style={{ background: 'currentColor' }} />
                    {healthLabel}
                </div>

                <div className="vicc-timestamp" title="Updates live while simulation runs">
                    Updated {fmtClock(now)}
                </div>

                <button
                    className="vicc-iconbtn"
                    onClick={() => navigate('safety', { severity: 'critical' })}
                    aria-label={`${openCritical} critical alerts, open Safety tab`}
                    title="Open critical alerts"
                >
                    <BellIcon />
                    {openCritical > 0 ? <span className="vicc-iconbtn__count">{openCritical}</span> : null}
                </button>
            </div>
        </header>
    )
}
