import React from 'react'

export interface MatrixCell {
    label: string
    color: string
    title?: string
    onClick?: () => void
}
interface Props {
    cells: MatrixCell[]
}

/** Status matrix grid (e.g. camera availability). */
export default function Matrix({ cells }: Props) {
    return (
        <div className="vicc-matrix">
            {cells.map((c, i) => (
                <div
                    key={i}
                    className="vicc-matrix__cell"
                    style={{ background: c.color, cursor: c.onClick ? 'pointer' : 'default' }}
                    title={c.title || c.label}
                    onClick={c.onClick}
                >
                    {c.label}
                </div>
            ))}
        </div>
    )
}
