import React, { useMemo, useState } from 'react'
import { useApp } from '../state/AppContext'
import { CAMERAS, ZONES, ZONE_MAP, PALETTE } from '../data/catalog'
import { PlusIcon, MinusIcon } from './Icons'

const STATUS_COLOR: Record<string, string> = { online: PALETTE.vibrant, degraded: PALETTE.amber, offline: '#6d8494' }
const OPEN = new Set(['active', 'acknowledged', 'investigating'])
const VB_W = 100
const VB_H = 56.25

// small schematic motif per zone, drawn in the title strip
function ZoneGlyph({ zoneId, x, y }: { zoneId: string; x: number; y: number }) {
    const s = { stroke: 'rgba(242,247,248,0.65)', strokeWidth: 0.3, fill: 'none' } as const
    switch (zoneId) {
        case 'ZN-PROC':
            return <g {...s}><rect x={x} y={y - 2.4} width="1.6" height="3.4" rx="0.4" /><rect x={x + 2} y={y - 1.6} width="1.6" height="2.6" rx="0.4" /></g>
        case 'ZN-PUMP':
            return <g {...s}><circle cx={x + 0.9} cy={y - 0.6} r="1.2" /><path d={`M${x + 2.1} ${y - 0.6} h1.4`} /></g>
        case 'ZN-TANK':
            return <g {...s}><ellipse cx={x + 1} cy={y - 0.6} rx="1.3" ry="1.6" /><ellipse cx={x + 3.1} cy={y - 0.6} rx="1.3" ry="1.6" /></g>
        case 'ZN-LOAD':
            return <g {...s}><rect x={x} y={y - 1.8} width="2.4" height="2.6" rx="0.3" /><path d={`M${x + 2.6} ${y + 0.8} h1.4 v-1.6`} /></g>
        case 'ZN-CONS':
            return <g {...s}><path d={`M${x} ${y + 0.8} l1.4 -3 l1.4 3`} /><path d={`M${x + 0.4} ${y - 0.3} h2`} /></g>
        default:
            return <g {...s}><path d={`M${x} ${y + 0.8} v-2.6 h3.4 v2.6`} /><path d={`M${x + 1.7} ${y - 1.8} v2.6`} /></g>
    }
}

export default function OperationalMap() {
    const { filters, selectedCameraId, selectCamera, events } = useApp()
    const [scale, setScale] = useState(1)
    const [hover, setHover] = useState<string | null>(null)

    const zones = ZONES.filter((z) => filters.siteId === 'all' || z.siteId === filters.siteId)
    const openEvents = useMemo(() => events.filter((e) => OPEN.has(e.status)), [events])

    const alertByCam = useMemo(() => {
        const m: Record<string, number> = {}
        openEvents.forEach((e) => (m[e.cameraId] = (m[e.cameraId] || 0) + 1))
        return m
    }, [openEvents])

    const riskByZone = useMemo(() => {
        const m: Record<string, number> = {}
        openEvents.forEach((e) => (m[e.zoneId] = (m[e.zoneId] || 0) + e.riskScore))
        return m
    }, [openEvents])

    const cols = Math.min(3, Math.max(1, zones.length))
    const rows = Math.ceil(zones.length / cols)
    const gap = 2.2
    const cw = (VB_W - gap * (cols + 1)) / cols
    const ch = (VB_H - gap * (rows + 1)) / rows
    const titleH = 5
    const hoverCam = hover ? CAMERAS.find((c) => c.id === hover) : null

    return (
        <div className="vicc-panel">
            <div className="vicc-panel__head">
                <div className="vicc-panel__title">
                    <span className="vicc-panel__dot" /> Operational Map <small>plant schematic · simulated digital twin</small>
                </div>
                <div className="vicc-row" style={{ gap: 6 }}>
                    <button className="vicc-iconbtn" style={{ width: 30, height: 30 }} onClick={() => setScale((s) => Math.min(2, +(s + 0.25).toFixed(2)))} aria-label="Zoom in"><PlusIcon size={14} /></button>
                    <button className="vicc-iconbtn" style={{ width: 30, height: 30 }} onClick={() => setScale((s) => Math.max(1, +(s - 0.25).toFixed(2)))} aria-label="Zoom out"><MinusIcon size={14} /></button>
                </div>
            </div>
            <div className="vicc-panel__body">
                <div className="vicc-map">
                    <svg viewBox={`0 0 ${VB_W} ${VB_H}`} preserveAspectRatio="xMidYMid meet">
                        <g transform={`translate(${VB_W / 2},${VB_H / 2}) scale(${scale}) translate(${-VB_W / 2},${-VB_H / 2})`}>
                            {zones.map((z, i) => {
                                const c = i % cols
                                const rI = Math.floor(i / cols)
                                const x = gap + c * (cw + gap)
                                const y = gap + rI * (ch + gap)
                                const risk = riskByZone[z.id] || 0
                                const heat = Math.min(0.2, risk / 900)
                                const zoneCams = CAMERAS.filter((cam) => cam.zoneId === z.id)
                                const per = Math.max(1, Math.ceil(Math.sqrt(zoneCams.length)))
                                const mrows = Math.ceil(zoneCams.length / per)
                                const bx = x + 1.6
                                const by = y + titleH + 1.2
                                const bw = cw - 3.2
                                const bh = ch - titleH - 2.4

                                return (
                                    <g key={z.id}>
                                        <rect x={x} y={y} width={cw} height={ch} rx={2.4} fill="rgba(18,34,46,0.72)" stroke="rgba(56,217,230,0.28)" strokeWidth={0.3} />
                                        {heat > 0.01 ? <rect x={x} y={y + titleH} width={cw} height={ch - titleH} rx={2} fill={`rgba(255,102,115,${heat})`} /> : null}
                                        {/* title strip */}
                                        <rect x={x} y={y} width={cw} height={titleH} rx={2.4} fill="rgba(7,20,31,0.9)" />
                                        <rect x={x} y={y + titleH - 2} width={cw} height={2} fill="rgba(7,20,31,0.9)" />
                                        <ZoneGlyph zoneId={z.id} x={x + 1.6} y={y + 3.4} />
                                        <text x={x + 6} y={y + 3.4} style={{ fill: 'var(--vc-white)', fontSize: 2.3, fontWeight: 700 }}>{z.name}</text>

                                        {zoneCams.map((cam, ci) => {
                                            const col = ci % per
                                            const rr = Math.floor(ci / per)
                                            const mx = bx + (bw / per) * (col + 0.5)
                                            const my = by + (bh / mrows) * (rr + 0.5)
                                            const color = STATUS_COLOR[cam.status]
                                            const alerts = alertByCam[cam.id] || 0
                                            const sel = cam.id === selectedCameraId
                                            return (
                                                <g
                                                    key={cam.id}
                                                    className="vicc-map__cam"
                                                    onClick={() => selectCamera(cam.id)}
                                                    onMouseEnter={() => setHover(cam.id)}
                                                    onMouseLeave={() => setHover((h) => (h === cam.id ? null : h))}
                                                >
                                                    <title>{cam.id} · {cam.name} — {alerts} open alert(s)</title>
                                                    {alerts > 0 ? (
                                                        <circle cx={mx} cy={my} r={1.9} fill="none" stroke={PALETTE.red} strokeWidth={0.4} opacity={0.75}>
                                                            <animate attributeName="r" values="1.5;2.3;1.5" dur="1.5s" repeatCount="indefinite" />
                                                        </circle>
                                                    ) : null}
                                                    {sel ? <circle cx={mx} cy={my} r={2} fill="none" stroke={PALETTE.white} strokeWidth={0.45} /> : null}
                                                    <circle cx={mx} cy={my} r={sel ? 1.3 : 0.95} fill={color} stroke="#04161a" strokeWidth={0.25} />
                                                </g>
                                            )
                                        })}
                                    </g>
                                )
                            })}
                        </g>
                    </svg>
                </div>
                <div className="vicc-map__legend">
                    <span className="vicc-legend-item"><span className="d" style={{ color: PALETTE.vibrant, background: PALETTE.vibrant }} /> Online</span>
                    <span className="vicc-legend-item"><span className="d" style={{ color: PALETTE.amber, background: PALETTE.amber }} /> Degraded</span>
                    <span className="vicc-legend-item"><span className="d" style={{ color: '#6d8494', background: '#6d8494' }} /> Offline</span>
                    <span className="vicc-legend-item"><span className="d" style={{ color: PALETTE.red, background: PALETTE.red }} /> Open alert</span>
                    <span className="vicc-legend-item" style={{ color: 'var(--vc-red)' }}>▦ Risk heatmap</span>
                    <span style={{ marginLeft: 'auto', fontSize: '0.7rem', color: 'var(--vc-muted)' }}>
                        {hoverCam ? `${hoverCam.id} · ${hoverCam.name} — ${alertByCam[hoverCam.id] || 0} alert(s)` : `${CAMERAS.filter((c) => filters.siteId === 'all' || c.siteId === filters.siteId).length} cameras · hover for detail`}
                    </span>
                </div>
            </div>
        </div>
    )
}
