import React, { useMemo, useState } from 'react'
import { useApp } from '../state/AppContext'
import EmbeddedCVFeed from '../components/EmbeddedCVFeed'
import DetectionDetail from '../components/DetectionDetail'
import IndustrialScene, { SCENE_ANCHORS } from '../components/IndustrialScene'
import { CAMERAS, CAMERA_MAP, CATEGORY_MAP, SEVERITY_COLOR, SEVERITY_RANK } from '../data/catalog'
import type { Detection } from '../data/types'
import { fmtTime, pct, severityLabel } from '../utils/format'

const STATUS_COLOR: Record<string, string> = { online: 'var(--vc-vibrant)', degraded: 'var(--vc-amber)', offline: '#6d8494' }

function CameraTile({ id }: { id: string }) {
    const { detections, selectedCameraId, selectCamera } = useApp()
    const cam = CAMERA_MAP[id]
    const sel = id === selectedCameraId

    const assigned = useMemo(() => {
        const pool = detections.filter((d) => d.cameraId === id)
        const used = new Set<string>()
        const out: { a: (typeof SCENE_ANCHORS)[number]; d: Detection }[] = []
        for (const a of SCENE_ANCHORS.slice(0, 3)) {
            const d = pool.find((x) => !used.has(x.id) && a.cats.includes(x.category)) || pool.find((x) => !used.has(x.id))
            if (d) {
                used.add(d.id)
                out.push({ a, d })
            }
        }
        return out
    }, [detections, id])

    return (
        <button
            onClick={() => selectCamera(id)}
            style={{ padding: 0, border: 'none', background: 'none', cursor: 'pointer', textAlign: 'left' }}
            aria-label={`Select ${cam.name}`}
        >
            <div className="vicc-feed__frame" style={{ border: sel ? '1px solid var(--vc-cyan)' : undefined, boxShadow: sel ? '0 0 12px rgba(56,217,230,0.4)' : undefined }}>
                <IndustrialScene env={cam.environment} />
                {assigned.map(({ a, d }) => {
                    const color = CATEGORY_MAP[d.category]?.color || SEVERITY_COLOR[d.severity]
                    return <span key={d.id} style={{ position: 'absolute', left: `${a.x}%`, top: `${a.y}%`, width: `${a.w}%`, height: `${a.h}%`, border: `1.5px solid ${color}`, borderRadius: 2, boxShadow: `0 0 8px ${color}55` }} />
                })}
                <div className="vicc-feed__meta" style={{ fontSize: '0.6rem' }}>
                    <span style={{ color: 'var(--vc-white)' }}>{cam.id}</span>
                    <span style={{ color: STATUS_COLOR[cam.status], fontWeight: 800 }}>● {cam.status}</span>
                </div>
            </div>
        </button>
    )
}

type SortKey = 'label' | 'category' | 'cameraId' | 'confidence' | 'severity' | 'riskScore' | 'timestamp'

export default function Monitoring() {
    const { filteredDetections, selectedCameraId, selectDetection, selectedDetectionId, filters } = useApp()
    const [sort, setSort] = useState<{ key: SortKey; dir: 1 | -1 }>({ key: 'timestamp', dir: -1 })

    const tiles = CAMERAS.filter((c) => filters.siteId === 'all' || c.siteId === filters.siteId).slice(0, 9)

    const rows = useMemo(() => {
        const copy = filteredDetections.slice(0, 120)
        copy.sort((a, b) => {
            let av: number | string
            let bv: number | string
            if (sort.key === 'severity') {
                av = SEVERITY_RANK[a.severity]
                bv = SEVERITY_RANK[b.severity]
            } else {
                av = a[sort.key] as number | string
                bv = b[sort.key] as number | string
            }
            if (av < bv) return -1 * sort.dir
            if (av > bv) return 1 * sort.dir
            return 0
        })
        return copy
    }, [filteredDetections, sort])

    const th = (key: SortKey, label: string) => (
        <th onClick={() => setSort((s) => ({ key, dir: s.key === key && s.dir === -1 ? 1 : -1 }))}>
            {label} {sort.key === key ? (sort.dir === -1 ? '▾' : '▴') : ''}
        </th>
    )

    return (
        <div className="vicc-stack vicc-fade" style={{ gap: 14 }}>
            <div className="vicc-row" style={{ alignItems: 'stretch' }}>
                <div className="vicc-panel" style={{ flex: '1 1 420px', minWidth: 320 }}>
                    <div className="vicc-panel__head">
                        <div className="vicc-panel__title"><span className="vicc-panel__dot" /> Camera Wall <small>{tiles.length} feeds · simulated</small></div>
                    </div>
                    <div className="vicc-panel__body">
                        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: 8 }}>
                            {tiles.map((c) => (
                                <div style={{ display: 'contents' }} key={c.id}>
                                    <CameraTile id={c.id} />
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
                <div style={{ flex: '1 1 460px', minWidth: 340 }}>
                    <EmbeddedCVFeed cameraId={selectedCameraId} />
                </div>
            </div>

            <div className="vicc-row" style={{ alignItems: 'stretch' }}>
                <div className="vicc-panel" style={{ flex: '2 1 520px', minWidth: 340 }}>
                    <div className="vicc-panel__head">
                        <div className="vicc-panel__title"><span className="vicc-panel__dot" /> Detections <small>{rows.length} shown</small></div>
                    </div>
                    <div className="vicc-panel__body vicc-scroll" style={{ maxHeight: 420 }}>
                        <table className="vicc-table">
                            <thead>
                                <tr>
                                    {th('label', 'Object')}
                                    {th('category', 'Category')}
                                    {th('cameraId', 'Camera')}
                                    {th('confidence', 'Conf')}
                                    {th('severity', 'Severity')}
                                    {th('riskScore', 'Risk')}
                                    {th('timestamp', 'Time')}
                                </tr>
                            </thead>
                            <tbody>
                                {rows.map((d: Detection) => (
                                    <tr key={d.id} className={d.id === selectedDetectionId ? 'is-selected' : ''} onClick={() => selectDetection(d.id)}>
                                        <td>{d.label}</td>
                                        <td>{CATEGORY_MAP[d.category]?.label}</td>
                                        <td>{d.cameraId}</td>
                                        <td className="num">{pct(d.confidence)}</td>
                                        <td><span className={`vicc-chip is-${d.severity}`}><span className="d" /> {severityLabel(d.severity)}</span></td>
                                        <td className="num">{d.riskScore}</td>
                                        <td className="num">{fmtTime(d.timestamp)}</td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>
                <div style={{ flex: '1 1 300px', minWidth: 280 }}>
                    <DetectionDetail />
                </div>
            </div>
        </div>
    )
}
