import React from 'react'
import { useApp } from '../state/AppContext'
import { CAMERA_MAP, CATEGORY_MAP, ZONE_MAP } from '../data/catalog'
import { fmtTime, pct, severityLabel } from '../utils/format'
import { ChevronRight } from './Icons'

export default function DetectionDetail() {
    const { detections, selectedDetectionId, events, navigate, selectEvent } = useApp()
    const det = detections.find((d) => d.id === selectedDetectionId)

    if (!det) {
        return (
            <div className="vicc-panel">
                <div className="vicc-panel__head">
                    <div className="vicc-panel__title">
                        <span className="vicc-panel__dot" /> Detection Intelligence
                    </div>
                </div>
                <div className="vicc-panel__body">
                    <div className="vicc-empty">Select a detection (bounding box, radar blip, or table row) to inspect its contextual intelligence.</div>
                </div>
            </div>
        )
    }

    const cam = CAMERA_MAP[det.cameraId]
    const zone = ZONE_MAP[det.zoneId]
    const cat = CATEGORY_MAP[det.category]
    const ev = det.eventId ? events.find((e) => e.id === det.eventId) : undefined

    return (
        <div className="vicc-panel vicc-fade">
            <div className="vicc-panel__head">
                <div className="vicc-panel__title">
                    <span className="vicc-panel__dot" style={{ background: cat?.color, boxShadow: `0 0 10px ${cat?.color}` }} /> Detection Intelligence <small>{det.id}</small>
                </div>
                <span className={`vicc-chip is-${det.severity}`}>
                    <span className="d" /> {severityLabel(det.severity)}
                </span>
            </div>
            <div className="vicc-panel__body">
                <div className="vicc-detail">
                    <div className="vicc-detail__row"><span>Object</span><b>{det.label}</b></div>
                    <div className="vicc-detail__row"><span>Tracking ID</span><b>{det.trackingId}</b></div>
                    <div className="vicc-detail__row"><span>Category</span><b>{cat?.label || det.category}</b></div>
                    <div className="vicc-detail__row"><span>Confidence</span><b>{pct(det.confidence)}</b></div>
                    <div className="vicc-detail__row"><span>Status</span><b>{ev ? ev.status.replace('_', ' ') : 'unlinked'}</b></div>
                    <div className="vicc-detail__row"><span>Risk Score</span><b>{det.riskScore} / 100</b></div>
                    <div className="vicc-detail__row"><span>Camera Source</span><b>{cam?.id} · {cam?.name}</b></div>
                    <div className="vicc-detail__row"><span>Zone</span><b>{zone?.name || det.zoneId}</b></div>
                    <div className="vicc-detail__row"><span>Time Detected</span><b>{fmtTime(det.timestamp)}</b></div>
                </div>

                {ev ? (
                    <div style={{ marginTop: 12 }}>
                        <div className="vicc-section-title">Recommended Response</div>
                        <p style={{ fontSize: '0.8rem', margin: '0 0 10px', color: 'var(--vc-white)' }}>{ev.recommended}</p>
                        <button
                            className="vicc-btn vicc-btn--primary vicc-btn--sm"
                            onClick={() => {
                                selectEvent(ev.id)
                                navigate('safety')
                            }}
                        >
                            View in Safety <ChevronRight size={13} />
                        </button>
                    </div>
                ) : (
                    <p className="vicc-note" style={{ marginTop: 10 }}>No safety event linked to this detection.</p>
                )}
            </div>
        </div>
    )
}
