import React, { useState } from 'react'
import { useApp } from '../state/AppContext'
import type { SafetyEvent } from '../data/types'
import { titleCase } from '../utils/format'
import { CheckIcon, UserIcon, BoltIcon, AlertIcon, FlagIcon, ShieldIcon, WrenchIcon } from './Icons'

const OWNERS = ['A. Okafor', 'R. Mehta', 'L. Haddad', 'S. Park', 'D. Novak', 'M. Costa']

const WORKFLOWS: { label: string; action: 'incident' | 'workflow' }[] = [
    { label: 'Safety Incident', action: 'incident' },
    { label: 'Equipment Inspection', action: 'workflow' },
    { label: 'Maintenance Work Order', action: 'workflow' },
    { label: 'Notify Site Supervisor', action: 'workflow' },
    { label: 'Security Investigation', action: 'workflow' },
    { label: 'Corrective Action', action: 'workflow' },
]

export default function EventActions({ event }: { event: SafetyEvent }) {
    const { actOnEvent } = useApp()
    const [owner, setOwner] = useState(event.owner || OWNERS[0])
    const closed = event.status === 'resolved' || event.status === 'false_positive'

    return (
        <div className="vicc-stack" style={{ gap: 12 }}>
            <div>
                <div className="vicc-section-title">Operator Actions</div>
                <div className="vicc-row" style={{ gap: 7 }}>
                    <button className="vicc-btn vicc-btn--sm" disabled={event.status !== 'active'} onClick={() => actOnEvent(event.id, 'acknowledge')}>
                        <CheckIcon size={13} /> Acknowledge
                    </button>
                    <button className="vicc-btn vicc-btn--sm" disabled={closed} onClick={() => actOnEvent(event.id, 'escalate')}>
                        <BoltIcon size={13} /> Escalate
                    </button>
                    <button className="vicc-btn vicc-btn--sm vicc-btn--danger" disabled={closed || event.isIncident} onClick={() => actOnEvent(event.id, 'incident', 'Safety Incident')}>
                        <AlertIcon size={13} /> Create Incident
                    </button>
                    <button className="vicc-btn vicc-btn--sm" disabled={closed} onClick={() => actOnEvent(event.id, 'false_positive')}>
                        <FlagIcon size={13} /> False Positive
                    </button>
                    <button className="vicc-btn vicc-btn--sm vicc-btn--go" disabled={closed} onClick={() => actOnEvent(event.id, 'resolve')}>
                        <CheckIcon size={13} /> Resolve
                    </button>
                </div>
                <div className="vicc-row" style={{ gap: 7, marginTop: 8, alignItems: 'center' }}>
                    <UserIcon size={14} />
                    <select className="vicc-select" style={{ minWidth: 130 }} value={owner} onChange={(e) => setOwner(e.target.value)} aria-label="Owner" disabled={closed}>
                        {OWNERS.map((o) => (
                            <option key={o} value={o}>{o}</option>
                        ))}
                    </select>
                    <button className="vicc-btn vicc-btn--sm" disabled={closed} onClick={() => actOnEvent(event.id, 'assign', owner)}>
                        Assign Owner
                    </button>
                </div>
            </div>

            <div>
                <div className="vicc-section-title">ServiceNow Workflow <span className="vicc-note">(simulated records)</span></div>
                <div className="vicc-row" style={{ gap: 7 }}>
                    {WORKFLOWS.map((w) => (
                        <button
                            key={w.label}
                            className="vicc-btn vicc-btn--sm"
                            disabled={closed}
                            onClick={() => actOnEvent(event.id, w.action, w.label)}
                        >
                            {w.action === 'incident' ? <AlertIcon size={13} /> : w.label.includes('Security') ? <ShieldIcon size={13} /> : <WrenchIcon size={13} />}
                            {w.label}
                        </button>
                    ))}
                </div>
            </div>

            {event.workflows.length > 0 ? (
                <div>
                    <div className="vicc-section-title">Generated Records</div>
                    <div className="vicc-stack" style={{ gap: 6 }}>
                        {event.workflows.map((w, i) => (
                            <div key={i} style={{ display: 'flex', justifyContent: 'space-between', gap: 10, fontSize: '0.76rem', alignItems: 'center' }}>
                                <span style={{ color: 'var(--vc-white)' }}>
                                    <b>{w.number}</b> · {w.type}
                                </span>
                                <span className="vicc-chip" style={{ color: 'var(--vc-cyan)', borderColor: 'var(--vc-line)', background: 'rgba(56,217,230,0.08)' }}>
                                    {titleCase(w.status)}
                                </span>
                            </div>
                        ))}
                    </div>
                </div>
            ) : null}
        </div>
    )
}
