import React, { useRef, useState } from 'react'
import { useApp } from '../state/AppContext'
import { CAMERA_MAP, CATEGORY_MAP, SEVERITY_COLOR, ENV_LABEL, CAMERAS } from '../data/catalog'
import type { Detection } from '../data/types'
import { fmtTime } from '../utils/format'
import { PlayIcon, PauseIcon, SwitchIcon, CaptureIcon, EyeIcon, EyeOffIcon, ExpandIcon } from './Icons'
import IndustrialScene, { SCENE_ANCHORS, type Anchor } from './IndustrialScene'

interface Props {
    cameraId?: string
    compact?: boolean
}

// Bind the camera's detections to fixed scene anchors: prefer a detection whose
// category matches the anchor's object, then fill remaining anchors in order.
function assign(cam: string, dets: Detection[]): { anchor: Anchor; det: Detection }[] {
    const pool = dets.filter((d) => d.cameraId === cam)
    const used = new Set<string>()
    const out: { anchor: Anchor; det: Detection }[] = []
    for (const anchor of SCENE_ANCHORS) {
        let det = pool.find((d) => !used.has(d.id) && anchor.cats.includes(d.category))
        if (!det) det = pool.find((d) => !used.has(d.id))
        if (det) {
            used.add(det.id)
            out.push({ anchor, det })
        }
    }
    return out
}

export default function LiveVision({ cameraId, compact }: Props) {
    const { selectedCameraId, selectCamera, selectDetection, selectedDetectionId, detections, simRunning, toggleSim, now, filters } = useApp()
    const camId = cameraId || selectedCameraId
    const cam = CAMERA_MAP[camId]
    const frameRef = useRef<HTMLDivElement>(null)
    const [showBoxes, setShowBoxes] = useState(true)
    const [flash, setFlash] = useState(false)
    const [toast, setToast] = useState('')

    const boxes = assign(camId, detections)

    const cycleCamera = () => {
        const online = CAMERAS.filter((c) => c.status === 'online' && (filters.siteId === 'all' || c.siteId === filters.siteId))
        if (online.length === 0) return
        const idx = online.findIndex((c) => c.id === camId)
        const next = online[(idx + 1) % online.length]
        selectCamera(next.id)
    }

    const screenshot = () => {
        setFlash(true)
        setToast('Screenshot captured (simulated)')
        window.setTimeout(() => setFlash(false), 320)
        window.setTimeout(() => setToast(''), 1600)
    }

    const fullscreen = () => {
        const el = frameRef.current
        if (el && el.requestFullscreen) el.requestFullscreen().catch(() => setToast('Fullscreen unavailable'))
        else setToast('Fullscreen unavailable in this view')
        if (!el?.requestFullscreen) window.setTimeout(() => setToast(''), 1600)
    }

    if (!cam) return <div className="vicc-empty">Camera not found.</div>

    const frame = (
        <div className="vicc-feed__frame" ref={frameRef}>
            <IndustrialScene env={cam.environment} />
            <div className="vicc-feed__scan">
                <div className="vicc-feed__scanline" style={simRunning ? undefined : { animationPlayState: 'paused' }} />
            </div>

            <div className="vicc-feed__meta">
                <span className="vicc-feed__rec">
                    <span className="d" /> REC
                </span>
                <span>{cam.id} · {fmtTime(now)}</span>
            </div>
            <div className="vicc-feed__env">{ENV_LABEL[cam.environment]}</div>

            {showBoxes
                ? boxes.map(({ anchor, det }) => {
                      // Colour by severity so violations read red/amber and normal
                      // detections read green — matching the reference semantics.
                      const color = SEVERITY_COLOR[det.severity] || CATEGORY_MAP[det.category]?.color
                      const sel = det.id === selectedDetectionId
                      const labelBelow = anchor.y < 16
                      return (
                          <button
                              key={det.id}
                              className={`vicc-box ${sel ? 'is-selected' : ''}`}
                              onClick={() => selectDetection(det.id)}
                              aria-label={`Detection ${det.id} ${det.label} ${Math.round(det.confidence * 100)}%`}
                              style={{
                                  left: `${anchor.x}%`,
                                  top: `${anchor.y}%`,
                                  width: `${anchor.w}%`,
                                  height: `${anchor.h}%`,
                                  color,
                                  borderColor: color,
                                  background: 'transparent',
                                  padding: 0,
                              }}
                          >
                              <span
                                  className="vicc-box__tag"
                                  style={labelBelow ? { top: 'calc(100% + 2px)' } : undefined}
                              >
                                  {det.label} · {Math.round(det.confidence * 100)}%
                              </span>
                              {sel ? (
                                  <>
                                      <span className="vicc-box__corner" style={{ top: -2, left: -2, borderRight: 'none', borderBottom: 'none' }} />
                                      <span className="vicc-box__corner" style={{ top: -2, right: -2, borderLeft: 'none', borderBottom: 'none' }} />
                                      <span className="vicc-box__corner" style={{ bottom: -2, left: -2, borderRight: 'none', borderTop: 'none' }} />
                                      <span className="vicc-box__corner" style={{ bottom: -2, right: -2, borderLeft: 'none', borderTop: 'none' }} />
                                  </>
                              ) : null}
                          </button>
                      )
                  })
                : null}

            {!simRunning ? <div className="vicc-feed__paused">PAUSED</div> : null}
            {flash ? <div style={{ position: 'absolute', inset: 0, background: 'rgba(242,247,248,0.85)' }} /> : null}
            {toast ? (
                <div
                    className="vicc-fade"
                    style={{
                        position: 'absolute', bottom: 12, right: 12, background: 'rgba(4,12,19,0.9)',
                        border: '1px solid var(--vc-line)', borderRadius: 8, padding: '6px 11px',
                        fontSize: '0.74rem', fontWeight: 700, color: 'var(--vc-cyan)',
                    }}
                >
                    {toast}
                </div>
            ) : null}
        </div>
    )

    if (compact) return <div className="vicc-feed">{frame}</div>

    return (
        <div className="vicc-panel vicc-feed">
            <div className="vicc-panel__head">
                <div className="vicc-panel__title">
                    <span className="vicc-panel__dot" /> Live Vision Feed <small>{cam.id} · {cam.name}</small>
                </div>
                <small style={{ color: 'var(--vc-muted)' }}>Simulated footage</small>
            </div>
            <div className="vicc-panel__body">
                {frame}
                <div className="vicc-feed__controls">
                    <button className="vicc-btn vicc-btn--sm" onClick={toggleSim}>
                        {simRunning ? <PauseIcon size={13} /> : <PlayIcon size={13} />} {simRunning ? 'Pause' : 'Play'}
                    </button>
                    <button className="vicc-btn vicc-btn--sm" onClick={cycleCamera}>
                        <SwitchIcon size={13} /> Camera Switch
                    </button>
                    <button className="vicc-btn vicc-btn--sm" onClick={screenshot}>
                        <CaptureIcon size={13} /> Screenshot
                    </button>
                    <button className="vicc-btn vicc-btn--sm" onClick={() => setShowBoxes((v) => !v)} aria-pressed={showBoxes}>
                        {showBoxes ? <EyeIcon size={13} /> : <EyeOffIcon size={13} />} Overlay {showBoxes ? 'On' : 'Off'}
                    </button>
                    <button className="vicc-btn vicc-btn--sm" onClick={fullscreen}>
                        <ExpandIcon size={13} /> Fullscreen
                    </button>
                    <span className="vicc-note">Drawn simulated scene · controls affect the simulation only.</span>
                </div>
            </div>
        </div>
    )
}
