import React from 'react'
import { useApp } from '../state/AppContext'
import EmbeddedCVFeed from '../components/EmbeddedCVFeed' // RECOVERY-EDIT: reuse Connected CV Feed
import DetectionDetail from '../components/DetectionDetail'
import Radar from '../components/Radar'
import OperationalMap from '../components/OperationalMap'
import InsightsSidebar from '../components/InsightsSidebar'
import { SEVERITY_RANK, SEVERITY_COLOR } from '../data/catalog'
import { fmtAgo } from '../utils/format'

const OPEN = new Set(['active', 'acknowledged', 'investigating'])

function CriticalAlerts() {
    const { filteredEvents, selectEvent, selectedEventId, now } = useApp()
    const rows = filteredEvents
        .filter((e) => OPEN.has(e.status) && (e.severity === 'critical' || e.severity === 'high'))
        .sort((a, b) => SEVERITY_RANK[b.severity] - SEVERITY_RANK[a.severity] || b.detectedAt - a.detectedAt)
        .slice(0, 8)

    return (
        <div className="vicc-panel">
            <div className="vicc-panel__head">
                <div className="vicc-panel__title">
                    <span className="vicc-panel__dot" style={{ background: 'var(--vc-red)', boxShadow: '0 0 10px var(--vc-red)' }} /> Critical Alerts
                </div>
                <small style={{ color: 'var(--vc-muted)' }}>{rows.length} open</small>
            </div>
            <div className="vicc-panel__body vicc-scroll" style={{ maxHeight: 300 }}>
                {rows.length === 0 ? <div className="vicc-empty">No open critical or high alerts.</div> : null}
                <div className="vicc-alerts">
                    {rows.map((e) => (
                        <button
                            key={e.id}
                            className={`vicc-alert sev-${e.severity} ${e.id === selectedEventId ? 'is-selected' : ''}`}
                            onClick={() => selectEvent(e.id)}
                            title={e.title}
                        >
                            <span className="vicc-alert__dot" style={{ color: SEVERITY_COLOR[e.severity], background: SEVERITY_COLOR[e.severity] }} />
                            <span className="vicc-alert__name">{e.title}</span>
                            <span className="vicc-alert__meta">
                                <span>{e.cameraId}</span>
                                <span className="st">{e.status.replace('_', ' ')}</span>
                                <span>{fmtAgo(e.detectedAt, now)}</span>
                            </span>
                        </button>
                    ))}
                </div>
            </div>
        </div>
    )
}

export default function Overview() {
    const { selectedCameraId } = useApp() // RECOVERY-EDIT
    return (
        <div className="vicc-ov vicc-fade">
            <div className="vicc-ov__col vicc-ov__main">
                <EmbeddedCVFeed cameraId={selectedCameraId} />
                <DetectionDetail />
                <OperationalMap />
            </div>
            <div className="vicc-ov__col vicc-ov__side">
                <div className="vicc-panel">
                    <div className="vicc-panel__head">
                        <div className="vicc-panel__title">
                            <span className="vicc-panel__dot" /> AI Radar Sweep <small>signature view</small>
                        </div>
                    </div>
                    <div className="vicc-panel__body">
                        <Radar size="md" />
                    </div>
                </div>
                <CriticalAlerts />
                <InsightsSidebar />
            </div>
        </div>
    )
}
