import React from 'react'
import { useApp } from './state/AppContext'
import Header from './components/Header'
import DemoBar from './components/DemoBar'
import KpiRibbon from './components/KpiRibbon'
import TabNav from './components/TabNav'
import Overview from './tabs/Overview'
import Monitoring from './tabs/Monitoring'
import RadarTab from './tabs/RadarTab'
import Safety from './tabs/Safety'
import Analytics from './tabs/Analytics'

export default function App() {
    const { tab } = useApp()

    return (
        <div className="vicc-app">
            <div className="vicc-topbar">
                <Header />
                <div className="vicc-topbar__mid">
                    <DemoBar />
                    <KpiRibbon />
                </div>
                <TabNav />
            </div>
            <main className="vicc-main">
                {tab === 'overview' ? <Overview /> : null}
                {tab === 'monitoring' ? <Monitoring /> : null}
                {tab === 'radar' ? <RadarTab /> : null}
                {tab === 'safety' ? <Safety /> : null}
                {tab === 'analytics' ? <Analytics /> : null}
            </main>
        </div>
    )
}
