import React, { useEffect, useMemo, useRef, useState } from 'react'
import { useApp, type CvTrack } from '../state/AppContext'
import LiveVision from './LiveVision'
import { severityLabel } from '../utils/format'

// Reads the configurable GitHub Pages URL injected by the UI Page
// (window.VICC_CV_URL from the x_snc_vision_int_0.cv_embed_url property).
function embedUrl(): string {
    const u = (window as unknown as { VICC_CV_URL?: string }).VICC_CV_URL
    return typeof u === 'string' ? u.trim() : ''
}

const OPEN = new Set(['active', 'acknowledged', 'investigating'])

export default function EmbeddedCVFeed({ cameraId }: { cameraId?: string }) {
    const { simRunning, navigate, ingestCv, events, selectEvent } = useApp()
    const url = embedUrl()
    const origin = useMemo(() => {
        try {
            return url ? new URL(url).origin : ''
        } catch {
            return ''
        }
    }, [url])

    const iframeRef = useRef<HTMLIFrameElement>(null)
    const readyRef = useRef(false)
    const [failed, setFailed] = useState(false)
    const [ready, setReady] = useState(false)
    const [last, setLast] = useState<CvTrack | null>(null)
    const [counts, setCounts] = useState<Record<string, number>>({})

    // Receive origin-validated messages from the embedded experience.
    useEffect(() => {
        if (!url) return
        const onMsg = (ev: MessageEvent) => {
            if (origin && ev.origin !== origin) return // origin validation
            const m = ev.data || {}
            if (m.source !== 'vicc-cv') return
            if (m.type === 'ready') {
                readyRef.current = true
                setReady(true)
                setFailed(false)
            } else if (m.type === 'detections' && m.payload && Array.isArray(m.payload.tracks)) {
                const tracks = m.payload.tracks as CvTrack[]
                ingestCv(tracks)
                const c: Record<string, number> = {}
                tracks.forEach((t) => {
                    const k = (t.category || 'other').toLowerCase()
                    c[k] = (c[k] || 0) + 1
                })
                setCounts(c)
            } else if (m.type === 'detectionSelected' && m.payload) {
                const t = m.payload as CvTrack
                ingestCv([t])
                setLast(t)
            }
        }
        window.addEventListener('message', onMsg)
        return () => window.removeEventListener('message', onMsg)
    }, [url, origin, ingestCv])

    // Sync pause/resume with the dashboard simulation state.
    useEffect(() => {
        const w = iframeRef.current?.contentWindow
        if (!w || !origin) return
        w.postMessage({ source: 'vicc-dashboard', type: simRunning ? 'resume' : 'pause' }, origin)
    }, [simRunning, origin])

    // If the frame never signals ready (blocked by CSP / X-Frame-Options), fall back.
    useEffect(() => {
        if (!url) return
        readyRef.current = false
        const t = window.setTimeout(() => {
            if (!readyRef.current) setFailed(true)
        }, 7000)
        return () => window.clearTimeout(t)
    }, [url])

    // Fallback: no URL configured, or embedding blocked → built-in drawn scene.
    if (!url || failed) {
        return (
            <div className="vicc-stack" style={{ gap: 8 }}>
                <LiveVision cameraId={cameraId} />
                <p className="vicc-note">
                    {url
                        ? 'Embedded GitHub feed blocked by security policy — showing built-in simulated scene.'
                        : 'Set property x_snc_vision_int_0.cv_embed_url to embed the GitHub-hosted feed. Showing built-in simulated scene.'}
                </p>
            </div>
        )
    }

    const openReviews = events.filter((e) => e.source === 'cv' && e.screening && OPEN.has(e.status))
    const isViolation = last && (last.severity === 'critical' || last.severity === 'high')

    return (
        <div className="vicc-panel vicc-feed">
            <div className="vicc-panel__head">
                <div className="vicc-panel__title">
                    <span className="vicc-panel__dot" style={{ background: ready ? 'var(--vc-vibrant)' : 'var(--vc-amber)', boxShadow: `0 0 10px ${ready ? 'var(--vc-vibrant)' : 'var(--vc-amber)'}` }} />
                    Connected CV Feed <small>{ready ? 'live inference' : 'connecting…'} · {origin}</small>
                </div>
                <small style={{ color: 'var(--vc-muted)' }}>camera / upload in-frame</small>
            </div>
            <div className="vicc-panel__body">
                <div className="vicc-feed__frame">
                    <iframe
                        ref={iframeRef}
                        src={url}
                        title="Embedded computer vision experience"
                        loading="lazy"
                        allow="camera; microphone; fullscreen"
                        sandbox="allow-scripts allow-same-origin"
                        referrerPolicy="origin"
                        style={{ width: '100%', height: '100%', border: 'none', display: 'block' }}
                        onError={() => setFailed(true)}
                    />
                </div>

                {/* Live category counts from the most recent inference heartbeat */}
                <div className="vicc-row" style={{ marginTop: 10, gap: 8, flexWrap: 'wrap' }}>
                    {Object.keys(counts).length === 0 ? (
                        <span className="vicc-note">Waiting for detections… allow camera or upload a video inside the frame.</span>
                    ) : (
                        Object.entries(counts).map(([k, n]) => (
                            <span key={k} className="vicc-chip" style={{ color: 'var(--vc-cyan)', borderColor: 'rgba(56,217,230,0.4)', background: 'rgba(56,217,230,0.1)' }}>
                                <span className="d" /> {k} · {n}
                            </span>
                        ))
                    )}
                </div>

                {/* Experimental fire/smoke screening reviews */}
                {openReviews.length > 0 ? (
                    <div className="vicc-row" style={{ marginTop: 10, gap: 8, alignItems: 'center' }}>
                        <span className="vicc-chip is-high"><span className="d" /> {openReviews.length} hazard review{openReviews.length > 1 ? 's' : ''}</span>
                        {openReviews.slice(0, 2).map((e) => (
                            <button
                                key={e.id}
                                className="vicc-btn vicc-btn--danger vicc-btn--sm"
                                onClick={() => {
                                    selectEvent(e.id)
                                    navigate('safety')
                                }}
                            >
                                {e.title} · {Math.round((e.screeningScore || 0) * 100)}% rel.
                            </button>
                        ))}
                    </div>
                ) : null}

                {last ? (
                    <div className="vicc-row" style={{ marginTop: 10, alignItems: 'center', gap: 10 }}>
                        <span className={`vicc-chip is-${last.severity}`}>
                            <span className="d" /> {severityLabel(last.severity)}
                        </span>
                        <span style={{ fontWeight: 800, fontSize: '0.82rem' }}>{last.label}</span>
                        <span style={{ color: 'var(--vc-muted)', fontSize: '0.74rem' }}>
                            {last.trackingId} · {Math.round((last.confidence || 0) * 100)}%
                        </span>
                        {isViolation ? (
                            <button className="vicc-btn vicc-btn--danger vicc-btn--sm" style={{ marginLeft: 'auto' }} onClick={() => navigate('safety', { severity: 'high' })}>
                                Review in Safety
                            </button>
                        ) : null}
                    </div>
                ) : null}

                <p className="vicc-note" style={{ marginTop: 8 }}>
                    Objects (person/vehicle) use real on-device AI inference. Fire/smoke is <b>experimental zero-shot screening</b> — scores are relative similarities ("% rel."), not calibrated fire-detection confidence; operators must verify before creating an incident.
                </p>
            </div>
        </div>
    )
}
