import React, { useEffect, useRef, useState } from 'react'

interface Props {
    series: number[]
    color?: string
    fill?: string
    height?: number
    xLabels?: string[]
    animated?: boolean
}

/** Generic area+line chart. Draws itself on mount via a stroke-dash reveal. */
export default function LineArea({
    series,
    color = '#38D9E6',
    fill = 'rgba(56,217,230,0.18)',
    height = 150,
    xLabels,
    animated = true,
}: Props) {
    const W = 320
    const H = height
    const pad = 22
    const n = series.length
    const max = Math.max(1, ...series)
    const stepX = n > 1 ? (W - pad * 2) / (n - 1) : 0
    const pts = series.map((v, i) => [pad + i * stepX, H - pad - (v / max) * (H - pad * 2)] as [number, number])
    const line = pts.map((p, i) => `${i ? 'L' : 'M'}${p[0].toFixed(1)},${p[1].toFixed(1)}`).join(' ')
    const area = pts.length
        ? `${line} L${(pad + (n - 1) * stepX).toFixed(1)},${H - pad} L${pad},${H - pad} Z`
        : ''

    const pathRef = useRef<SVGPathElement>(null)
    const [dash, setDash] = useState(0)
    useEffect(() => {
        if (!animated || !pathRef.current) return
        const len = pathRef.current.getTotalLength()
        setDash(len)
        const id = requestAnimationFrame(() => setDash(0))
        return () => cancelAnimationFrame(id)
    }, [series.join(','), animated])

    const every = Math.max(1, Math.ceil(n / 5))

    return (
        <div className="vicc-chart">
            <svg viewBox={`0 0 ${W} ${H}`} role="img" aria-label="Line chart">
                <line className="vicc-chart__axis" x1={pad} y1={H - pad} x2={W - pad} y2={H - pad} />
                {area ? <path d={area} fill={fill} stroke="none" /> : null}
                <path
                    ref={pathRef}
                    d={line}
                    fill="none"
                    stroke={color}
                    strokeWidth={2}
                    strokeLinejoin="round"
                    style={{
                        strokeDasharray: dash || undefined,
                        strokeDashoffset: dash,
                        transition: 'stroke-dashoffset 900ms ease',
                    }}
                />
                {pts.length ? (
                    <circle cx={pts[pts.length - 1][0]} cy={pts[pts.length - 1][1]} r={3} fill={color} />
                ) : null}
                {xLabels
                    ? xLabels.map((l, i) =>
                          i % every === 0 ? (
                              <text key={i} x={pad + i * stepX} y={H - 5} textAnchor="middle">
                                  {l}
                              </text>
                          ) : null,
                      )
                    : null}
            </svg>
        </div>
    )
}
