import type {
    Detection,
    SafetyEvent,
    Anomaly,
    Insight,
    Dataset,
    CategoryId,
    Severity,
    EventStatus,
    LifecycleStage,
    AuditEntry,
} from './types'
import { CATEGORIES, CAMERAS, CAMERA_MAP, SITES, ZONES, ZONE_MAP, SEVERITY_RANK } from './catalog'

// Deterministic PRNG (mulberry32) so the demo dataset is stable across reloads.
function rng(seed: number) {
    let a = seed >>> 0
    return () => {
        a |= 0
        a = (a + 0x6d2b79f5) | 0
        let t = Math.imul(a ^ (a >>> 15), 1 | a)
        t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
        return ((t ^ (t >>> 14)) >>> 0) / 4294967296
    }
}

const r = rng(20261004)
const pick = <T,>(arr: T[]): T => arr[Math.floor(r() * arr.length)]
const range = (min: number, max: number) => min + r() * (max - min)
const HOUR = 3600_000
const NOW = Date.UTC(2026, 9, 4, 14, 30) // fixed "last updated" baseline

const CATEGORY_SEVERITY: Record<CategoryId, Severity[]> = {
    person: ['low', 'low', 'medium'],
    vehicle: ['low', 'medium'],
    truck: ['low', 'medium'],
    forklift: ['medium', 'high'],
    equipment: ['low', 'medium'],
    pump: ['low', 'medium', 'high'],
    pipeline: ['low', 'medium'],
    smoke: ['high', 'critical'],
    fire: ['critical'],
    helmet: ['medium', 'high'],
    vest: ['medium', 'high'],
    intrusion: ['high', 'critical'],
}

const LABEL: Record<CategoryId, string> = {
    person: 'Person', vehicle: 'Vehicle', truck: 'Truck', forklift: 'Forklift',
    equipment: 'Equipment', pump: 'Pump', pipeline: 'Pipeline Component', smoke: 'Smoke',
    fire: 'Fire', helmet: 'Missing Helmet', vest: 'Missing Vest', intrusion: 'Restricted-Zone Intrusion',
}

function makeDetection(i: number): Detection {
    const cam = pick(CAMERAS.filter((c) => c.status !== 'offline'))
    const cat = pick(CATEGORIES).id
    const sev = pick(CATEGORY_SEVERITY[cat])
    const conf = cat === 'fire' || cat === 'smoke' ? range(0.9, 0.99) : range(0.8, 0.985)
    const risk = Math.min(100, Math.round(SEVERITY_RANK[sev] * 18 + conf * 20 + range(0, 14)))
    const id = `DET-${String(1000 + i)}`
    return {
        id,
        trackingId: `TRK-${String(4200 + i)}`,
        category: cat,
        confidence: Math.round(conf * 1000) / 1000,
        severity: sev,
        riskScore: risk,
        cameraId: cam.id,
        zoneId: cam.zoneId,
        siteId: cam.siteId,
        timestamp: Math.round(NOW - r() * 24 * HOUR),
        tracked: r() > 0.25,
        box: { x: range(8, 62), y: range(12, 58), w: range(10, 26), h: range(14, 30) },
        radar: {
            angle: (cam.angle + range(-18, 18) + 360) % 360,
            distance: Math.max(0.08, Math.min(0.96, cam.distance + range(-0.12, 0.12))),
        },
        label: LABEL[cat],
    }
}

// Storytelling scenarios (fixed cameras).
interface Scenario {
    key: string; cam: string; cat: CategoryId; sev: Severity; title: string
    recommended: string; status: EventStatus; stage: LifecycleStage; incident: boolean; owner: string | null
}
const SCENARIOS: Scenario[] = [
    { key: 'helmet', cam: 'CAM-07', cat: 'helmet', sev: 'high', title: 'Worker detected without safety helmet', recommended: 'Dispatch EHS officer; enforce PPE compliance in Loading Zone B.', status: 'active', stage: 'alert_generated', incident: false, owner: null },
    { key: 'smoke', cam: 'CAM-12', cat: 'smoke', sev: 'critical', title: 'Smoke detected near compressor unit', recommended: 'Trigger fire-watch protocol; inspect compressor; notify control room.', status: 'investigating', stage: 'action_assigned', incident: true, owner: 'A. Okafor' },
    { key: 'intrusion', cam: 'CAM-03', cat: 'intrusion', sev: 'critical', title: 'Unauthorized entry into restricted zone', recommended: 'Dispatch security; lock down Restricted Perimeter gate.', status: 'active', stage: 'human_review', incident: true, owner: null },
    { key: 'forklift', cam: 'CAM-19', cat: 'forklift', sev: 'high', title: 'Forklift proximity warning near pedestrians', recommended: 'Alert bay supervisor; enforce segregated traffic routing.', status: 'acknowledged', stage: 'risk_evaluated', incident: false, owner: 'R. Mehta' },
    { key: 'vehicle', cam: 'CAM-22', cat: 'vehicle', sev: 'high', title: 'Vehicle anomaly in pedestrian-only area', recommended: 'Verify authorization; reroute vehicle; review access policy.', status: 'investigating', stage: 'action_assigned', incident: true, owner: 'L. Haddad' },
    { key: 'pump', cam: 'CAM-15', cat: 'pump', sev: 'high', title: 'Pump visual anomaly — possible leak signature', recommended: 'Initiate equipment inspection; schedule maintenance work order.', status: 'acknowledged', stage: 'risk_evaluated', incident: true, owner: 'A. Okafor' },
]

const OWNERS = ['A. Okafor', 'R. Mehta', 'L. Haddad', 'S. Park', 'D. Novak', 'M. Costa']

function audit(detectedAt: number, status: EventStatus, owner: string | null): AuditEntry[] {
    const a: AuditEntry[] = [
        { at: detectedAt, actor: 'Vision Engine', action: 'Object Detected', detail: 'Simulated detection classified by rule-based engine.' },
        { at: detectedAt + 2000, actor: 'Vision Engine', action: 'Event Classified', detail: 'Severity and category assigned.' },
        { at: detectedAt + 4000, actor: 'Risk Model', action: 'Risk Evaluated', detail: 'Risk score computed from severity and confidence.' },
        { at: detectedAt + 6000, actor: 'Alert Service', action: 'Alert Generated', detail: 'Operational alert raised to command center.' },
    ]
    if (status !== 'active') a.push({ at: detectedAt + 60_000, actor: owner || 'Operator', action: 'Acknowledged', detail: 'Reviewed by human operator.' })
    if (status === 'investigating' || status === 'resolved') a.push({ at: detectedAt + 180_000, actor: owner || 'Operator', action: 'Action Assigned', detail: 'Corrective action assigned to owner.' })
    if (status === 'resolved') a.push({ at: detectedAt + 600_000, actor: owner || 'Operator', action: 'Resolved', detail: 'Event resolved and KPIs updated.' })
    return a
}

export function buildDataset(): Dataset {
    const detections: Detection[] = []
    for (let i = 0; i < 268; i++) detections.push(makeDetection(i))

    const events: SafetyEvent[] = []
    let incidentCount = 0

    // Scenario-driven events linked to fresh detections on fixed cameras.
    SCENARIOS.forEach((s, i) => {
        const cam = CAMERA_MAP[s.cam]
        const detectedAt = NOW - (i + 1) * 7 * 60_000
        const det: Detection = {
            id: `DET-${900 + i}`,
            trackingId: `TRK-${5100 + i}`,
            category: s.cat,
            confidence: Math.round(range(0.9, 0.98) * 1000) / 1000,
            severity: s.sev,
            riskScore: Math.round(60 + SEVERITY_RANK[s.sev] * 8 + range(0, 8)),
            cameraId: cam.id,
            zoneId: cam.zoneId,
            siteId: cam.siteId,
            timestamp: detectedAt,
            tracked: true,
            box: { x: range(20, 45), y: range(20, 40), w: range(16, 26), h: range(18, 28) },
            radar: { angle: cam.angle, distance: cam.distance },
            label: LABEL[s.cat],
            eventId: `EVT-${100 + i}`,
        }
        detections.push(det)
        const incidentNumber = s.incident ? `DEMO-INC-${String(++incidentCount).padStart(4, '0')}` : undefined
        events.push({
            id: `EVT-${100 + i}`,
            title: s.title,
            category: s.cat,
            severity: s.sev,
            confidence: det.confidence,
            riskScore: det.riskScore,
            siteId: cam.siteId,
            zoneId: cam.zoneId,
            cameraId: cam.id,
            detectionId: det.id,
            detectedAt,
            status: s.status,
            stage: s.stage,
            owner: s.owner,
            recommended: s.recommended,
            isIncident: s.incident,
            incidentNumber,
            workflows: s.incident
                ? [{ type: 'Safety Incident', number: incidentNumber!, status: s.status === 'resolved' ? 'closed' : 'in_progress', createdAt: detectedAt + 60_000, assignedTo: s.owner || undefined }]
                : [],
            audit: audit(detectedAt, s.status, s.owner),
            scenarioKey: s.key,
        })
    })

    // Additional generated safety/security events from high-severity detections.
    const candidates = detections
        .filter((d) => !d.eventId && ['helmet', 'vest', 'intrusion', 'smoke', 'fire', 'forklift'].includes(d.category))
        .slice(0, 30)
    const STATUSES: EventStatus[] = ['active', 'acknowledged', 'investigating', 'resolved']
    candidates.forEach((d, i) => {
        const status = STATUSES[i % STATUSES.length]
        const owner = status === 'active' ? null : OWNERS[i % OWNERS.length]
        const isIncident = d.severity === 'critical' && incidentCount < 6 && status !== 'resolved'
        const incidentNumber = isIncident ? `DEMO-INC-${String(++incidentCount).padStart(4, '0')}` : undefined
        const eid = `EVT-${200 + i}`
        d.eventId = eid
        const stage: LifecycleStage =
            status === 'active' ? 'alert_generated' : status === 'acknowledged' ? 'human_review' : status === 'investigating' ? 'action_assigned' : 'resolution'
        events.push({
            id: eid,
            title: `${LABEL[d.category]} flagged on ${d.cameraId}`,
            category: d.category,
            severity: d.severity,
            confidence: d.confidence,
            riskScore: d.riskScore,
            siteId: d.siteId,
            zoneId: d.zoneId,
            cameraId: d.cameraId,
            detectionId: d.id,
            detectedAt: d.timestamp,
            status,
            stage,
            owner,
            recommended: 'Review detection and dispatch appropriate response team.',
            isIncident,
            incidentNumber,
            workflows: incidentNumber
                ? [{ type: 'Safety Incident', number: incidentNumber, status: 'in_progress', createdAt: d.timestamp + 60_000, assignedTo: owner || undefined }]
                : [],
            audit: audit(d.timestamp, status, owner),
        })
    })

    const anomalies: Anomaly[] = ZONES.flatMap((z, zi) =>
        [0, 1].map((k): Anomaly => {
            const cam = CAMERAS.find((c) => c.zoneId === z.id)!
            const types = ['Thermal signature drift', 'Repeated motion in idle zone', 'Vibration-correlated blur', 'Unusual dwell time', 'Visual leak signature', 'Flow irregularity']
            return {
                id: `ANO-${zi}${k}`,
                zoneId: z.id,
                cameraId: cam.id,
                type: types[(zi + k) % types.length],
                description: `${types[(zi + k) % types.length]} observed in ${z.name}.`,
                frequency: Math.round(range(3, 22)),
                trend: Math.round(range(-18, 42)),
                severity: pick<Severity>(['low', 'medium', 'high']),
            }
        }),
    )

    const insights: Insight[] = [
        { id: 'INS-1', title: 'Repeated helmet violations detected in Loading Bays', evidence: ['EVT-100'], riskLevel: 'high', basis: 'Rule-based pattern (3+ events / 6h)', confidence: 0.92, impact: 'PPE non-compliance increases injury liability.', recommendation: 'Brief Loading Bays shift leads; add PPE checkpoint.', zoneId: 'ZN-LOAD' },
        { id: 'INS-2', title: 'Unusual vehicle activity increased near Gate 03', evidence: ['EVT-104'], riskLevel: 'medium', basis: 'Rule-based trend (+38% vs prior period)', confidence: 0.84, impact: 'Potential unauthorized access to pedestrian zone.', recommendation: 'Review gate access policy; verify authorizations.', zoneId: 'ZN-REST' },
        { id: 'INS-3', title: 'Pump Area shows elevated visual anomaly frequency', evidence: ['EVT-105'], riskLevel: 'high', basis: 'Rule-based anomaly clustering', confidence: 0.88, impact: 'Possible early equipment degradation / leak.', recommendation: 'Schedule equipment inspection and maintenance.', zoneId: 'ZN-PUMP' },
        { id: 'INS-4', title: 'Restricted-zone intrusions up vs previous period', evidence: ['EVT-102'], riskLevel: 'critical', basis: 'Rule-based comparison (+2 vs prior 24h)', confidence: 0.9, impact: 'Security exposure at critical infrastructure.', recommendation: 'Increase perimeter patrols; audit access logs.', zoneId: 'ZN-REST' },
    ]

    return {
        sites: SITES,
        zones: ZONES,
        cameras: CAMERAS,
        categories: CATEGORIES,
        detections: detections.sort((a, b) => b.timestamp - a.timestamp),
        events: events.sort((a, b) => b.detectedAt - a.detectedAt),
        anomalies,
        insights,
        generatedAt: NOW,
    }
}

export const DATASET: Dataset = buildDataset()
export { NOW as BASELINE_NOW }
