import React, { useState } from 'react'
import { useApp } from '../state/AppContext'
import { ZONE_MAP } from '../data/catalog'
import { pct, severityLabel } from '../utils/format'
import Modal from './Modal'
import type { Insight } from '../data/types'
import { ChevronRight } from './Icons'

export default function InsightsSidebar() {
    const { dataset, events, navigate, selectEvent } = useApp()
    const [active, setActive] = useState<Insight | null>(null)

    const investigate = (ins: Insight) => {
        const evId = ins.evidence.find((id) => id.startsWith('EVT'))
        if (evId && events.some((e) => e.id === evId)) {
            selectEvent(evId)
            navigate('safety')
        } else {
            navigate('safety')
        }
        setActive(null)
    }

    return (
        <div className="vicc-panel">
            <div className="vicc-panel__head">
                <div className="vicc-panel__title">
                    <span className="vicc-panel__dot" /> AI Insights
                </div>
                <small style={{ color: 'var(--vc-muted)' }}>explainable</small>
            </div>
            <div className="vicc-panel__body">
                <p className="vicc-note" style={{ marginBottom: 10 }}>
                    Rule-based demo insights — NOT real AI model inference. Derived from simulated event patterns.
                </p>
                {dataset.insights.map((ins) => (
                    <div className="vicc-insight" key={ins.id}>
                        <div className="vicc-insight__title">{ins.title}</div>
                        <div className="vicc-insight__meta">
                            <span className={`vicc-chip is-${ins.riskLevel}`}><span className="d" /> {severityLabel(ins.riskLevel)}</span>
                            <span>Confidence {pct(ins.confidence, 0)}</span>
                            <span>· {ins.basis}</span>
                            {ins.zoneId ? <span>· {ZONE_MAP[ins.zoneId]?.name}</span> : null}
                        </div>
                        <div className="vicc-insight__rec"><b>Impact:</b> {ins.impact}</div>
                        <div className="vicc-insight__rec" style={{ marginTop: 4 }}><b>Recommendation:</b> {ins.recommendation}</div>
                        <button className="vicc-btn vicc-btn--ghost vicc-btn--sm" style={{ marginTop: 8 }} onClick={() => setActive(ins)}>
                            Explain / Investigate <ChevronRight size={13} />
                        </button>
                    </div>
                ))}
            </div>

            {active ? (
                <Modal
                    title={active.title}
                    onClose={() => setActive(null)}
                    footer={
                        <>
                            <button className="vicc-btn vicc-btn--ghost" onClick={() => setActive(null)}>Close</button>
                            <button className="vicc-btn vicc-btn--primary" onClick={() => investigate(active)}>Investigate in Safety</button>
                        </>
                    }
                >
                    <div className="vicc-stack" style={{ gap: 10 }}>
                        <div><span className="vicc-section-title">Evidence</span>
                            <ul style={{ margin: 0, paddingLeft: 18, fontSize: '0.8rem' }}>
                                {active.evidence.map((e) => <li key={e}>{e}</li>)}
                            </ul>
                        </div>
                        <div><span className="vicc-section-title">Rule Basis</span><p style={{ margin: 0, fontSize: '0.82rem' }}>{active.basis} · confidence {pct(active.confidence, 0)}</p></div>
                        <div><span className="vicc-section-title">Business Impact</span><p style={{ margin: 0, fontSize: '0.82rem' }}>{active.impact}</p></div>
                        <div><span className="vicc-section-title">Recommended Next Action</span><p style={{ margin: 0, fontSize: '0.82rem' }}>{active.recommendation}</p></div>
                        <p className="vicc-note">This explanation is generated from deterministic rules on simulated data, not a trained model.</p>
                    </div>
                </Modal>
            ) : null}
        </div>
    )
}
