import React from 'react'

interface State {
    error: Error | null
}

// Converts any render-time crash into a visible, themed message (instead of a
// blank white screen) and logs details to the console for diagnostics.
export default class ErrorBoundary extends React.Component<{ children?: React.ReactNode }, State> {
    state: State = { error: null }

    static getDerivedStateFromError(error: Error): State {
        return { error }
    }

    componentDidCatch(error: Error) {
        // eslint-disable-next-line no-console
        console.error('VICC render error:', error)
    }

    render() {
        const self = this as any
        const err: Error | null = self.state.error
        if (err) {
            return (
                <div
                    role="alert"
                    style={{
                        fontFamily: "'Lato', Arial, sans-serif",
                        background: '#07141f',
                        color: '#f2f7f8',
                        minHeight: '100vh',
                        padding: '40px',
                        boxSizing: 'border-box',
                    }}
                >
                    <h1 style={{ color: '#38d9e6', margin: '0 0 10px' }}>Vision Intelligence — render error</h1>
                    <p style={{ color: '#9fb4c0', margin: '0 0 16px' }}>
                        The dashboard hit a client-side error while rendering. Details below (also in the browser console).
                    </p>
                    <pre
                        style={{
                            whiteSpace: 'pre-wrap',
                            background: '#111f2b',
                            border: '1px solid #ff6673',
                            borderRadius: 10,
                            padding: 16,
                            color: '#ffbe55',
                            fontSize: 13,
                            overflow: 'auto',
                        }}
                    >
                        {String(err.stack || err.message || err)}
                    </pre>
                    <button
                        onClick={() => self.setState({ error: null })}
                        style={{
                            marginTop: 16,
                            background: 'linear-gradient(135deg, #38d9e6, #0e7f8c)',
                            color: '#04161a',
                            border: 'none',
                            borderRadius: 9,
                            padding: '8px 14px',
                            fontWeight: 700,
                            cursor: 'pointer',
                        }}
                    >
                        Retry
                    </button>
                </div>
            )
        }
        return self.props.children
    }
}
