import React, { useEffect, useRef, useState } from 'react'
import { useApp } from '../state/AppContext'
import type { TabId } from '../state/AppContext'
import type { Kpi } from '../data/selectors'
import type { Filters } from '../data/selectors'
import { ArrowUpIcon, ArrowDownIcon } from './Icons'

function sparkPoints(seed: number): number[] {
    let a = seed
    const pts: number[] = []
    for (let i = 0; i < 12; i++) {
        a = (a * 9301 + 49297) % 233280
        pts.push(a / 233280)
    }
    return pts
}

function Spark({ keyStr, up }: { keyStr: string; up: boolean }) {
    const seed = keyStr.split('').reduce((s, c) => s + c.charCodeAt(0), 0)
    const vals = sparkPoints(seed)
    const w = 54
    const h = 18
    const step = w / (vals.length - 1)
    const d = vals.map((v, i) => `${i ? 'L' : 'M'}${(i * step).toFixed(1)},${(h - v * h).toFixed(1)}`).join(' ')
    return (
        <svg className="vicc-kpi__spark" width={w} height={h} viewBox={`0 0 ${w} ${h}`} aria-hidden="true">
            <path d={d} fill="none" stroke={up ? 'var(--vc-vibrant)' : 'var(--vc-red)'} strokeWidth={1.4} />
        </svg>
    )
}

function KpiCard({ kpi }: { kpi: Kpi }) {
    const { navigate } = useApp()
    const prev = useRef(kpi.value)
    const [flash, setFlash] = useState(false)
    useEffect(() => {
        if (prev.current !== kpi.value) {
            prev.current = kpi.value
            setFlash(true)
            const t = window.setTimeout(() => setFlash(false), 700)
            return () => window.clearTimeout(t)
        }
    }, [kpi.value])

    const up = kpi.trend >= 0
    const good = up === kpi.goodWhenUp

    const onClick = () => {
        const patch: Partial<Filters> = {}
        if (kpi.drill.category) patch.category = kpi.drill.category
        if (kpi.drill.severity) patch.severity = kpi.drill.severity
        navigate(kpi.drill.tab as TabId, Object.keys(patch).length ? patch : undefined)
    }

    return (
        <button
            className={`vicc-kpi tone-${kpi.tone}`}
            onClick={onClick}
            title={`Drill into ${kpi.label}`}
            style={flash ? { borderColor: 'var(--vc-cyan)', boxShadow: '0 0 18px rgba(56,217,230,0.4)' } : undefined}
        >
            <Spark keyStr={kpi.key} up={good} />
            <div className="vicc-kpi__label">{kpi.label}</div>
            <div className="vicc-kpi__value" style={flash ? { color: 'var(--vc-cyan)', transition: 'color 300ms' } : { transition: 'color 300ms' }}>
                {kpi.value}
            </div>
            <div className="vicc-kpi__foot">
                <span className={`vicc-kpi__trend ${good ? 'up' : 'down'}`}>
                    {up ? <ArrowUpIcon size={11} /> : <ArrowDownIcon size={11} />}
                    {Math.abs(kpi.trend)}%
                </span>
                {kpi.sub ? <span className="vicc-kpi__sub">{kpi.sub}</span> : <span className="vicc-kpi__sub">vs prev</span>}
            </div>
        </button>
    )
}

export default function KpiRibbon() {
    const { kpis } = useApp()
    return (
        <div className="vicc-kpis" role="list" aria-label="Key performance indicators">
            {kpis.map((k) => (
                <div style={{ display: 'contents' }} key={k.key}>
                    <KpiCard kpi={k} />
                </div>
            ))}
        </div>
    )
}
