import React, { useEffect, useRef } from 'react'
import { CloseIcon } from './Icons'

interface Props {
    title: string
    onClose: () => void
    children?: React.ReactNode
    footer?: React.ReactNode
}

export default function Modal({ title, onClose, children, footer }: Props) {
    const ref = useRef<HTMLDivElement>(null)

    useEffect(() => {
        const onKey = (e: KeyboardEvent) => {
            if (e.key === 'Escape') onClose()
        }
        window.addEventListener('keydown', onKey)
        ref.current?.focus()
        return () => window.removeEventListener('keydown', onKey)
    }, [onClose])

    return (
        <div className="vicc-overlay" onClick={onClose} role="presentation">
            <div
                className="vicc-modal vicc-fade"
                role="dialog"
                aria-modal="true"
                aria-label={title}
                tabIndex={-1}
                ref={ref}
                onClick={(e) => e.stopPropagation()}
            >
                <div className="vicc-modal__head">
                    <strong>{title}</strong>
                    <button className="vicc-iconbtn" onClick={onClose} aria-label="Close dialog">
                        <CloseIcon />
                    </button>
                </div>
                <div className="vicc-modal__body">{children}</div>
                {footer ? <div className="vicc-modal__foot">{footer}</div> : null}
            </div>
        </div>
    )
}
