import type { Severity } from '../data/types'

/** HH:MM:SS (24h). */
export function fmtTime(ts: number): string {
    return new Date(ts).toLocaleTimeString('en-US', {
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
        hour12: false,
    })
}

/** Date + time for the header "last updated" readout. */
export function fmtClock(ts: number): string {
    const d = new Date(ts)
    const date = d.toLocaleDateString('en-US', { month: 'short', day: '2-digit' })
    return `${date} · ${fmtTime(ts)}`
}

/** Compact relative time ("12s ago", "4m ago", "3h ago"). */
export function fmtAgo(ts: number, now: number): string {
    const s = Math.max(0, Math.round((now - ts) / 1000))
    if (s < 60) return `${s}s ago`
    const m = Math.round(s / 60)
    if (m < 60) return `${m}m ago`
    const h = Math.round(m / 60)
    if (h < 24) return `${h}h ago`
    return `${Math.round(h / 24)}d ago`
}

/** 0..1 -> "96.2%". */
export function pct(v: number, digits = 1): string {
    return `${(v * 100).toFixed(digits)}%`
}

export function severityLabel(s: Severity): string {
    return s.charAt(0).toUpperCase() + s.slice(1)
}

export function titleCase(s: string): string {
    return s.replace(/_/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase())
}

/**
 * Polar -> cartesian with 0deg = North (up), 90deg = East (right).
 * `distance` is a 0..1 fraction of radius `r`.
 */
export function polar(angleDeg: number, distance: number, cx: number, cy: number, r: number): { x: number; y: number } {
    const a = (angleDeg - 90) * (Math.PI / 180)
    return { x: cx + Math.cos(a) * distance * r, y: cy + Math.sin(a) * distance * r }
}
