import React from 'react'

interface Props {
    bins: { bucket: string; count: number }[]
    color?: string
}

/** Vertical histogram. */
export default function Histogram({ bins, color = '#A6E66E' }: Props) {
    const W = 320
    const H = 150
    const pad = 26
    const max = Math.max(1, ...bins.map((b) => b.count))
    const n = bins.length
    const slot = (W - pad * 2) / Math.max(1, n)
    const bw = slot * 0.6
    return (
        <div className="vicc-chart">
            <svg viewBox={`0 0 ${W} ${H}`} role="img" aria-label="Histogram">
                <line className="vicc-chart__axis" x1={pad} y1={H - pad} x2={W - pad} y2={H - pad} />
                {bins.map((b, i) => {
                    const h = (b.count / max) * (H - pad * 2)
                    const x = pad + i * slot + (slot - bw) / 2
                    const y = H - pad - h
                    return (
                        <g key={i}>
                            <rect x={x} y={y} width={bw} height={h} rx={3} fill={color} opacity={0.85}>
                                <title>{`${b.bucket}: ${b.count}`}</title>
                            </rect>
                            {b.count > 0 ? (
                                <text x={x + bw / 2} y={y - 4} textAnchor="middle" style={{ fill: 'var(--vc-white)', fontSize: 9, fontWeight: 700 }}>
                                    {b.count}
                                </text>
                            ) : null}
                            <text x={x + bw / 2} y={H - pad + 12} textAnchor="middle">
                                {b.bucket}
                            </text>
                        </g>
                    )
                })}
            </svg>
        </div>
    )
}
