import React from 'react'

export interface Slice {
    label: string
    value: number
    color: string
}
interface Props {
    slices: Slice[]
    size?: number
    centerLabel?: string
    onSlice?: (index: number) => void
}

function pt(cx: number, cy: number, r: number, ang: number) {
    const a = (ang - 90) * (Math.PI / 180)
    return { x: cx + r * Math.cos(a), y: cy + r * Math.sin(a) }
}

/** Donut chart with optional clickable slices + legend. */
export default function Donut({ slices, size = 180, centerLabel, onSlice }: Props) {
    const total = slices.reduce((s, x) => s + x.value, 0)
    const cx = size / 2
    const cy = size / 2
    const r = size / 2 - 6
    let acc = 0

    return (
        <div className="vicc-chart" style={{ display: 'flex', gap: 14, alignItems: 'center', flexWrap: 'wrap' }}>
            <svg viewBox={`0 0 ${size} ${size}`} width={size} height={size} role="img" aria-label="Donut chart">
                {total === 0 ? (
                    <circle cx={cx} cy={cy} r={r} fill="none" stroke="var(--vc-line)" strokeWidth={2} />
                ) : (
                    slices.map((s, i) => {
                        const frac = s.value / total
                        const a0 = acc * 360
                        acc += frac
                        const a1 = acc * 360
                        const p0 = pt(cx, cy, r, a0)
                        const p1 = pt(cx, cy, r, a1)
                        const large = a1 - a0 > 180 ? 1 : 0
                        const d = `M${cx},${cy} L${p0.x.toFixed(2)},${p0.y.toFixed(2)} A${r},${r} 0 ${large} 1 ${p1.x.toFixed(2)},${p1.y.toFixed(2)} Z`
                        return (
                            <path
                                key={i}
                                d={d}
                                fill={s.color}
                                opacity={0.9}
                                stroke="var(--vc-navy)"
                                strokeWidth={1}
                                style={{ cursor: onSlice ? 'pointer' : 'default' }}
                                onClick={onSlice ? () => onSlice(i) : undefined}
                            >
                                <title>{`${s.label}: ${s.value}`}</title>
                            </path>
                        )
                    })
                )}
                <circle cx={cx} cy={cy} r={r * 0.58} fill="var(--vc-charcoal)" />
                <text x={cx} y={cy - 2} textAnchor="middle" style={{ fill: 'var(--vc-white)', fontSize: 18, fontWeight: 800 }}>
                    {total}
                </text>
                <text x={cx} y={cy + 14} textAnchor="middle">
                    {centerLabel || 'total'}
                </text>
            </svg>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, minmax(0, 1fr))', gap: '3px 10px', minWidth: 150, flex: 1 }}>
                {slices.map((s, i) => (
                    <button
                        key={i}
                        className="vicc-legend-item"
                        onClick={onSlice ? () => onSlice(i) : undefined}
                        style={{ background: 'none', border: 'none', cursor: onSlice ? 'pointer' : 'default', color: 'var(--vc-muted)', padding: 0, fontSize: '0.68rem', justifyContent: 'flex-start' }}
                    >
                        <span className="d" style={{ color: s.color, background: s.color }} />
                        {s.label} · {s.value}
                    </button>
                ))}
            </div>
        </div>
    )
}
