import React, { createContext, useContext, useState, useMemo, useCallback, useEffect, useRef } from 'react'
import type { Detection, SafetyEvent, EventStatus, LifecycleStage, RadarFilter, Severity, CategoryId } from '../data/types'
import { DATASET } from '../data/dataset'
import { CAMERA_MAP, SEVERITY_RANK } from '../data/catalog'
import { computeKpis, filterDetections, filterEvents, type Filters } from '../data/selectors'

export const TABS = ['overview', 'monitoring', 'radar', 'safety', 'analytics'] as const
export type TabId = (typeof TABS)[number]

// A detection track received from the embedded GitHub CV experience (vicc-cv).
export interface CvTrack {
    trackingId: string
    label: string
    category: string
    severity: Severity
    confidence: number
}

const clamp01 = (n: number) => (typeof n === 'number' && isFinite(n) ? Math.max(0, Math.min(1, n)) : 0)
function hashStr(s: string): number {
    let h = 2166136261
    for (let i = 0; i < s.length; i++) {
        h ^= s.charCodeAt(i)
        h = Math.imul(h, 16777619)
    }
    return (h >>> 0) % 1000
}
// Map the embedded model's classes onto our category taxonomy.
const CV_CAT: Record<string, CategoryId> = {
    person: 'person', fire: 'fire', flame: 'fire', smoke: 'smoke',
    car: 'vehicle', bus: 'vehicle', motorcycle: 'vehicle', bicycle: 'vehicle', vehicle: 'vehicle',
    truck: 'truck', forklift: 'forklift',
}
function mapCvCategory(c: string): CategoryId {
    return CV_CAT[(c || '').toLowerCase()] || 'equipment'
}

let demoSeq = 0

interface DemoState {
    running: boolean
    step: number
    label: string
    detectionId: string | null
    eventId: string | null
}

interface AppValue {
    dataset: typeof DATASET
    now: number
    filters: Filters
    setFilter: (patch: Partial<Filters>) => void
    resetFilters: () => void
    tab: TabId
    navigate: (tab: TabId, patch?: Partial<Filters>) => void
    selectedCameraId: string
    selectCamera: (id: string) => void
    selectedDetectionId: string | null
    selectDetection: (id: string | null) => void
    selectedEventId: string | null
    selectEvent: (id: string | null) => void
    radarFilter: RadarFilter
    setRadarFilter: (f: RadarFilter) => void
    detections: Detection[]
    events: SafetyEvent[]
    filteredDetections: Detection[]
    filteredEvents: SafetyEvent[]
    kpis: ReturnType<typeof computeKpis>
    simRunning: boolean
    toggleSim: () => void
    // event lifecycle
    actOnEvent: (id: string, action: EventAction, payload?: string) => void
    // embedded CV feed
    cvLive: boolean
    ingestCv: (tracks: CvTrack[]) => void
    // demo
    demo: DemoState
    startDemo: () => void
    pauseSim: () => void
    resetDemo: () => void
}

export type EventAction =
    | 'acknowledge'
    | 'assign'
    | 'escalate'
    | 'incident'
    | 'false_positive'
    | 'resolve'
    | 'workflow'

const DEFAULT_FILTERS: Filters = { siteId: 'all', category: 'all', severity: 'all', window: '24h' }

const AppContext = createContext<AppValue | null>(null)

function readTab(): TabId {
    const t = new URLSearchParams(window.location.search).get('tab') as TabId
    return TABS.includes(t) ? t : 'overview'
}

const STAGE_BY_STATUS: Record<EventStatus, LifecycleStage> = {
    active: 'alert_generated',
    acknowledged: 'human_review',
    investigating: 'action_assigned',
    resolved: 'resolution',
    false_positive: 'resolution',
}

const OWNERS = ['A. Okafor', 'R. Mehta', 'L. Haddad', 'S. Park']

export function AppProvider({ children }: { children?: React.ReactNode }) {
    const [filters, setFilters] = useState<Filters>(DEFAULT_FILTERS)
    const [tab, setTab] = useState<TabId>(readTab)
    const [selectedCameraId, setSelectedCameraId] = useState('CAM-07')
    const [selectedDetectionId, setSelectedDetectionId] = useState<string | null>(null)
    const [selectedEventId, setSelectedEventId] = useState<string | null>(null)
    const [radarFilter, setRadarFilter] = useState<RadarFilter>('all')
    const [detections, setDetections] = useState<Detection[]>(DATASET.detections)
    const [events, setEvents] = useState<SafetyEvent[]>(DATASET.events)
    const [now, setNow] = useState<number>(DATASET.generatedAt)
    const [simRunning, setSimRunning] = useState(true)
    const [cvLive, setCvLive] = useState(false)
    const [demo, setDemo] = useState<DemoState>({ running: false, step: 0, label: '', detectionId: null, eventId: null })
    const demoTimer = useRef<number | null>(null)
    const nowRef = useRef(now)
    nowRef.current = now
    const selectedCamIdRef = useRef(selectedCameraId)
    selectedCamIdRef.current = selectedCameraId
    const cvSeq = useRef(0)
    const cvTrackMap = useRef<Record<string, string>>({})

    // Live clock advances while the simulation runs (drives "last updated" + live feel).
    useEffect(() => {
        if (!simRunning) return
        const h = window.setInterval(() => setNow((n) => n + 1000), 1000)
        return () => window.clearInterval(h)
    }, [simRunning])

    useEffect(() => {
        const onPop = () => setTab(readTab())
        window.addEventListener('popstate', onPop)
        return () => window.removeEventListener('popstate', onPop)
    }, [])

    const navigate = useCallback((next: TabId, patch?: Partial<Filters>) => {
        setTab(next)
        if (patch) setFilters((f) => ({ ...f, ...patch }))
        const params = new URLSearchParams(window.location.search)
        params.set('tab', next)
        const path = `${window.location.pathname}?${params.toString()}`
        const title = `Vision Intelligence — ${next.charAt(0).toUpperCase() + next.slice(1)}`
        if (window.self !== window.top && (window as any).CustomEvent?.fireTop) {
            ;(window as any).CustomEvent.fireTop('magellanNavigator.permalink.set', { relativePath: path, title })
        }
        window.history.pushState({ tab: next }, '', path)
        document.title = title
    }, [])

    const setFilter = useCallback((patch: Partial<Filters>) => setFilters((f) => ({ ...f, ...patch })), [])
    const resetFilters = useCallback(() => setFilters(DEFAULT_FILTERS), [])

    const selectCamera = useCallback((id: string) => {
        setSelectedCameraId(id)
        setSelectedDetectionId(null)
    }, [])

    const selectDetection = useCallback((id: string | null) => {
        setSelectedDetectionId(id)
        if (id) {
            const d = DATASET.detections.concat(detectionsRef.current).find((x) => x.id === id)
            if (d) {
                setSelectedCameraId(d.cameraId)
                if (d.eventId) setSelectedEventId(d.eventId)
            }
        }
    }, [])

    const detectionsRef = useRef(detections)
    detectionsRef.current = detections

    const selectEvent = useCallback((id: string | null) => {
        setSelectedEventId(id)
        if (id) {
            const e = eventsRef.current.find((x) => x.id === id)
            if (e) {
                setSelectedCameraId(e.cameraId)
                setSelectedDetectionId(e.detectionId)
            }
        }
    }, [])

    const eventsRef = useRef(events)
    eventsRef.current = events

    const actOnEvent = useCallback((id: string, action: EventAction, payload?: string) => {
        setEvents((list) =>
            list.map((e) => {
                if (e.id !== id) return e
                const at = Date.now()
                const audit = e.audit.slice()
                let status = e.status
                let owner = e.owner
                const workflows = e.workflows.slice()
                let incidentNumber = e.incidentNumber
                let isIncident = e.isIncident
                if (action === 'acknowledge') {
                    status = 'acknowledged'
                    audit.push({ at, actor: 'Operator', action: 'Acknowledged', detail: 'Alert acknowledged by operator.' })
                } else if (action === 'assign') {
                    owner = payload || OWNERS[0]
                    audit.push({ at, actor: 'Operator', action: 'Owner Assigned', detail: `Assigned to ${owner}.` })
                } else if (action === 'escalate') {
                    status = 'investigating'
                    audit.push({ at, actor: 'Operator', action: 'Escalated', detail: 'Event escalated for investigation.' })
                } else if (action === 'incident') {
                    isIncident = true
                    status = status === 'active' ? 'investigating' : status
                    incidentNumber = incidentNumber || `DEMO-INC-${String(1000 + demoSeq++).slice(1)}`
                    workflows.push({ type: payload || 'Safety Incident', number: incidentNumber, status: 'in_progress', createdAt: at, assignedTo: owner || undefined })
                    audit.push({ at, actor: 'Operator', action: 'Incident Created', detail: `${payload || 'Safety Incident'} ${incidentNumber} created (simulated).` })
                } else if (action === 'workflow') {
                    const num = `DEMO-WF-${String(1000 + demoSeq++).slice(1)}`
                    workflows.push({ type: payload || 'Work Order', number: num, status: 'open', createdAt: at, assignedTo: owner || undefined })
                    audit.push({ at, actor: 'Operator', action: 'Workflow Initiated', detail: `${payload || 'Work Order'} ${num} initiated (simulated).` })
                } else if (action === 'false_positive') {
                    status = 'false_positive'
                    audit.push({ at, actor: 'Operator', action: 'Marked False Positive', detail: 'Detection dismissed as false positive.' })
                } else if (action === 'resolve') {
                    status = 'resolved'
                    workflows.forEach((w) => (w.status = 'closed'))
                    audit.push({ at, actor: owner || 'Operator', action: 'Resolved', detail: 'Event resolved; KPIs updated.' })
                }
                return { ...e, status, owner, workflows, incidentNumber, isIncident, stage: STAGE_BY_STATUS[status], audit }
            }),
        )
    }, [])

    // ---- Ingest detections from the embedded GitHub CV feed (vicc-cv) ----
    // Person/vehicle tracks feed the detection stream (radar, recent detections,
    // analytics). Fire/smoke screening raises a de-duplicated "Review Required"
    // safety event that the operator must confirm/reject before any incident.
    const ingestCv = useCallback((tracks: CvTrack[]) => {
        if (!tracks || !tracks.length) return
        setCvLive(true)
        const cam = CAMERA_MAP[selectedCamIdRef.current] || CAMERA_MAP['CAM-07']
        const at = nowRef.current

        setDetections((list) => {
            const next = list.slice()
            tracks.forEach((t) => {
                if (!t || !t.trackingId) return
                const cat = mapCvCategory(t.category)
                const sev: Severity = t.severity || 'low'
                const conf = clamp01(t.confidence)
                const existingId = cvTrackMap.current[t.trackingId]
                const id = existingId || `DET-CV-${cvSeq.current++}`
                const det: Detection = {
                    id,
                    trackingId: t.trackingId,
                    category: cat,
                    confidence: conf,
                    severity: sev,
                    riskScore: Math.min(100, SEVERITY_RANK[sev] * 22 + Math.round(conf * 12)),
                    cameraId: cam.id,
                    zoneId: cam.zoneId,
                    siteId: cam.siteId,
                    timestamp: at,
                    tracked: true,
                    box: { x: 22, y: 30, w: 16, h: 24 },
                    radar: { angle: (cam.angle + (hashStr(t.trackingId) % 40) - 20 + 360) % 360, distance: 0.35 + (hashStr(t.trackingId) % 50) / 100 },
                    label: t.label || cat,
                    source: 'cv',
                }
                const idx = existingId ? next.findIndex((d) => d.id === existingId) : -1
                if (idx >= 0) next[idx] = { ...next[idx], ...det, eventId: next[idx].eventId }
                else {
                    cvTrackMap.current[t.trackingId] = id
                    next.unshift(det)
                }
            })
            return next
        })

        // Fire/smoke screening → Review Required event (de-duplicated per category).
        const OPEN = new Set(['active', 'acknowledged', 'investigating'])
        tracks.forEach((t) => {
            const cat = mapCvCategory(t.category)
            if (cat !== 'fire' && cat !== 'smoke') return
            const score = clamp01(t.confidence)
            setEvents((list) => {
                const dup = list.find((e) => e.source === 'cv' && e.category === cat && OPEN.has(e.status))
                if (dup) {
                    return list.map((e) =>
                        e.id === dup.id
                            ? {
                                  ...e,
                                  screeningScore: score,
                                  detectedAt: at,
                                  audit: e.audit
                                      .concat({ at, actor: 'CV Screening', action: 'Screening Updated', detail: `Relative ${cat} similarity ${(score * 100).toFixed(0)}% rel. (uncalibrated).` })
                                      .slice(-14),
                              }
                            : e,
                    )
                }
                const eid = `EVT-CV-${cvSeq.current++}`
                const ev: SafetyEvent = {
                    id: eid,
                    title: `Review Required: Possible ${cat === 'fire' ? 'Flame' : 'Smoke'}`,
                    category: cat,
                    severity: 'high',
                    confidence: 0,
                    riskScore: 70,
                    siteId: cam.siteId,
                    zoneId: cam.zoneId,
                    cameraId: cam.id,
                    detectionId: cvTrackMap.current[t.trackingId] || '',
                    detectedAt: at,
                    status: 'active',
                    stage: 'human_review',
                    owner: null,
                    recommended: 'Experimental AI screening flagged a possible hazard. An operator must visually verify before creating an incident or work order.',
                    isIncident: false,
                    workflows: [],
                    audit: [{ at, actor: 'CV Screening', action: 'Screening Alert', detail: `Experimental zero-shot ${cat} screening raised a review (${(score * 100).toFixed(0)}% rel. similarity — NOT a calibrated fire-detection confidence).` }],
                    source: 'cv',
                    screening: true,
                    screeningScore: score,
                    reviewRequired: true,
                    scenarioKey: 'cv-screening',
                }
                return [ev, ...list]
            })
        })
    }, [])

    // ---- Demo scenario engine ----
    const clearDemo = useCallback(() => {
        if (demoTimer.current) window.clearInterval(demoTimer.current)
        demoTimer.current = null
    }, [])

    const resetDemo = useCallback(() => {
        clearDemo()
        setDetections(DATASET.detections)
        setEvents(DATASET.events)
        setDemo({ running: false, step: 0, label: '', detectionId: null, eventId: null })
        setSelectedDetectionId(null)
        setSelectedEventId(null)
    }, [clearDemo])

    const startDemo = useCallback(() => {
        clearDemo()
        setSimRunning(true)
        const cam = CAMERA_MAP['CAM-07']
        const did = `DET-DEMO-${demoSeq}`
        const eid = `EVT-DEMO-${demoSeq}`
        demoSeq++
        const t = DATASET.generatedAt
        const det: Detection = {
            id: did, trackingId: `TRK-DEMO`, category: 'helmet', confidence: 0.97, severity: 'critical',
            riskScore: 88, cameraId: 'CAM-07', zoneId: cam.zoneId, siteId: cam.siteId, timestamp: t,
            tracked: true, box: { x: 34, y: 28, w: 22, h: 30 }, radar: { angle: cam.angle, distance: cam.distance },
            label: 'Missing Helmet', eventId: eid,
        }
        setTab('overview')
        setSelectedCameraId('CAM-07')
        setDemo({ running: true, step: 1, label: 'New detection: worker without helmet on CAM-07', detectionId: did, eventId: eid })
        setDetections((list) => [det, ...list])
        setSelectedDetectionId(did)

        const steps: Array<() => void> = [
            () => setDemo((d) => ({ ...d, step: 2, label: 'Radar blip acquired · bounding box locked' })),
            () => {
                const ev: SafetyEvent = {
                    id: eid, title: 'Worker detected without safety helmet (demo)', category: 'helmet', severity: 'critical',
                    confidence: 0.97, riskScore: 88, siteId: cam.siteId, zoneId: cam.zoneId, cameraId: 'CAM-07',
                    detectionId: did, detectedAt: t, status: 'active', stage: 'alert_generated', owner: null,
                    recommended: 'Dispatch EHS officer; enforce PPE compliance.', isIncident: false, workflows: [],
                    audit: [{ at: t, actor: 'Vision Engine', action: 'Object Detected', detail: 'Demo detection raised.' }],
                    scenarioKey: 'demo',
                }
                setEvents((list) => [ev, ...list])
                setSelectedEventId(eid)
                setDemo((d) => ({ ...d, step: 3, label: 'Risk alert generated · severity CRITICAL' }))
            },
            () => {
                actOnEvent(eid, 'incident', 'Safety Incident')
                setDemo((d) => ({ ...d, step: 4, label: 'Safety Incident created (simulated)' }))
            },
            () => {
                actOnEvent(eid, 'assign', 'A. Okafor')
                setDemo((d) => ({ ...d, step: 5, label: 'Corrective action assigned · A. Okafor' }))
            },
            () => {
                actOnEvent(eid, 'resolve')
                setDemo((d) => ({ ...d, step: 6, label: 'Resolved · KPIs updated' }))
            },
            () => {
                clearDemo()
                setDemo((d) => ({ ...d, running: false, label: 'Demo complete — end-to-end lifecycle shown' }))
            },
        ]
        let i = 0
        demoTimer.current = window.setInterval(() => {
            steps[i]?.()
            i++
            if (i >= steps.length) clearDemo()
        }, 2200)
    }, [actOnEvent, clearDemo])

    const pauseSim = useCallback(() => setSimRunning((s) => !s), [])
    const toggleSim = pauseSim

    useEffect(() => () => clearDemo(), [clearDemo])

    const filteredDetections = useMemo(() => filterDetections({ ...DATASET, detections }, filters, now), [detections, filters, now])
    const filteredEvents = useMemo(() => filterEvents(DATASET, events, filters), [events, filters])
    const kpis = useMemo(() => computeKpis({ ...DATASET, detections }, events, filters, now), [detections, events, filters, now])

    const value: AppValue = {
        dataset: DATASET, now, filters, setFilter, resetFilters, tab, navigate,
        selectedCameraId, selectCamera, selectedDetectionId, selectDetection,
        selectedEventId, selectEvent, radarFilter, setRadarFilter,
        detections, events, filteredDetections, filteredEvents, kpis,
        simRunning, toggleSim, actOnEvent, demo, startDemo, pauseSim, resetDemo,
        cvLive, ingestCv,
    }

    return <AppContext.Provider value={value}>{children}</AppContext.Provider>
}

export function useApp(): AppValue {
    const ctx = useContext(AppContext)
    if (!ctx) throw new Error('useApp must be used within AppProvider')
    return ctx
}
