import React from 'react'
import { useApp } from '../state/AppContext'
import { PlayIcon, PauseIcon } from './Icons'

export default function DemoBar() {
    const { demo, startDemo, pauseSim, resetDemo, simRunning } = useApp()
    const showStepper = demo.running || demo.step > 0

    return (
        <div className="vicc-demobar" role="region" aria-label="Demo controls">
            <button className="vicc-btn vicc-btn--go" onClick={startDemo}>
                <PlayIcon size={14} /> Run Demo Scenario
            </button>
            <button className="vicc-btn" onClick={pauseSim}>
                {simRunning ? <PauseIcon size={14} /> : <PlayIcon size={14} />}
                {simRunning ? 'Pause Simulation' : 'Resume Simulation'}
            </button>
            <button className="vicc-btn vicc-btn--ghost" onClick={resetDemo}>
                Reset Demo
            </button>

            <span className="vicc-demobar__status">
                {demo.label || 'Idle — press Run Demo Scenario for an end-to-end walkthrough.'}
            </span>

            {showStepper ? (
                <span style={{ display: 'inline-flex', gap: 4, alignItems: 'center' }} aria-label={`Demo step ${demo.step} of 6`}>
                    {[1, 2, 3, 4, 5, 6].map((n) => (
                        <span
                            key={n}
                            style={{
                                width: 16,
                                height: 6,
                                borderRadius: 3,
                                background: n <= demo.step ? 'var(--vc-vibrant)' : 'rgba(255,255,255,0.12)',
                                boxShadow: n === demo.step ? '0 0 8px var(--vc-vibrant)' : 'none',
                                transition: 'background 200ms',
                            }}
                        />
                    ))}
                </span>
            ) : null}

            <span className="vicc-note" style={{ width: '100%' }}>
                Simulated data — no real cameras, CV models, or ServiceNow records are involved.
            </span>
        </div>
    )
}
