import React, { useMemo } from 'react'
import { useApp } from '../state/AppContext'
import LineArea from '../components/charts/LineArea'
import Donut from '../components/charts/Donut'
import Bars from '../components/charts/Bars'
import Histogram from '../components/charts/Histogram'
import Matrix from '../components/charts/Matrix'
import { CATEGORIES, CAMERAS, SITES, SEVERITY_COLOR, PALETTE } from '../data/catalog'
import {
    detectionsOverTime,
    categoryCounts,
    violationsByZone,
    severityDistribution,
    topRiskZones,
    confidenceHistogram,
    repeatViolations,
    SEVERITIES,
} from '../data/selectors'
import { fmtTime, severityLabel } from '../utils/format'

const STATUS_COLOR: Record<string, string> = { online: PALETTE.vibrant, degraded: PALETTE.amber, offline: '#6d8494' }

function Panel({ title, children }: { title: string; children?: React.ReactNode }) {
    return (
        <div className="vicc-panel">
            <div className="vicc-panel__head">
                <div className="vicc-panel__title"><span className="vicc-panel__dot" /> {title}</div>
            </div>
            <div className="vicc-panel__body">{children}</div>
        </div>
    )
}

export default function Analytics() {
    const { filteredDetections, filteredEvents, filters, setFilter, resetFilters, navigate, now } = useApp()

    const overTime = useMemo(() => detectionsOverTime(filteredDetections, now), [filteredDetections, now])
    const cats = useMemo(() => categoryCounts(filteredDetections), [filteredDetections])
    const zoneViol = useMemo(() => violationsByZone(filteredEvents).filter((z) => z.count > 0), [filteredEvents])
    const sevDist = useMemo(() => severityDistribution(filteredEvents), [filteredEvents])
    const riskZones = useMemo(() => topRiskZones(filteredEvents), [filteredEvents])
    const confHist = useMemo(() => confidenceHistogram(filteredDetections), [filteredDetections])
    const repeats = useMemo(() => repeatViolations(filteredEvents), [filteredEvents])

    const respSeries = useMemo(() => {
        const arr: number[] = []
        filteredEvents.forEach((e) => {
            const ack = e.audit.find((a) => a.action.toLowerCase().includes('acknowledg'))
            if (ack) arr.push(Math.max(0, (ack.at - e.detectedAt) / 60000))
        })
        return arr
    }, [filteredEvents])
    const avgResp = respSeries.length ? respSeries.reduce((s, x) => s + x, 0) / respSeries.length : 0

    const resolutionSeries = useMemo(() => {
        const buckets = 8
        const span = 24 * 3600_000
        const start = now - span
        const size = span / buckets
        const out = new Array(buckets).fill(0)
        filteredEvents
            .filter((e) => e.status === 'resolved')
            .forEach((e) => {
                const idx = Math.min(buckets - 1, Math.max(0, Math.floor((e.detectedAt - start) / size)))
                out[idx]++
            })
        return out
    }, [filteredEvents, now])

    const camCells = CAMERAS.map((c) => ({
        label: c.id.replace('CAM-', ''),
        color: STATUS_COLOR[c.status],
        title: `${c.id} · ${c.name} — ${c.status}`,
    }))

    return (
        <div className="vicc-stack vicc-fade" style={{ gap: 14 }}>
            <div className="vicc-panel">
                <div className="vicc-panel__body vicc-row vicc-analytics__filters" style={{ alignItems: 'flex-end' }}>
                    <label className="vicc-field"><span className="vicc-field__label">Site</span>
                        <select className="vicc-select" value={filters.siteId} onChange={(e) => setFilter({ siteId: e.target.value })}>
                            <option value="all">All Sites</option>
                            {SITES.map((s) => <option key={s.id} value={s.id}>{s.code}</option>)}
                        </select>
                    </label>
                    <label className="vicc-field"><span className="vicc-field__label">Category</span>
                        <select className="vicc-select" value={filters.category} onChange={(e) => setFilter({ category: e.target.value })}>
                            <option value="all">All Categories</option>
                            {CATEGORIES.map((c) => <option key={c.id} value={c.id}>{c.label}</option>)}
                        </select>
                    </label>
                    <label className="vicc-field"><span className="vicc-field__label">Severity</span>
                        <select className="vicc-select" value={filters.severity} onChange={(e) => setFilter({ severity: e.target.value })}>
                            <option value="all">All Severities</option>
                            {SEVERITIES.map((s) => <option key={s} value={s}>{severityLabel(s)}</option>)}
                        </select>
                    </label>
                    <label className="vicc-field"><span className="vicc-field__label">Time Window</span>
                        <select className="vicc-select" value={filters.window} onChange={(e) => setFilter({ window: e.target.value as '1h' | '6h' | '24h' })}>
                            <option value="1h">Last 1h</option>
                            <option value="6h">Last 6h</option>
                            <option value="24h">Last 24h</option>
                        </select>
                    </label>
                    <button className="vicc-btn vicc-btn--ghost" onClick={resetFilters}>Reset Filters</button>
                    <span className="vicc-note" style={{ marginLeft: 'auto' }}>All charts recompute from the filtered simulated dataset.</span>
                </div>
            </div>

            <div className="vicc-charts vicc-analytics">
                <Panel title="Object Detections Over Time">
                    <LineArea series={overTime.map((p) => p.count)} xLabels={overTime.map((p) => fmtTime(p.t).slice(0, 5))} height={120} />
                </Panel>

                <Panel title="Object Categories (click to filter)">
                    <Donut
                        slices={cats.map((c) => ({ label: c.label, value: c.count, color: c.color }))}
                        centerLabel="objects"
                        size={132}
                        onSlice={(i) => setFilter({ category: cats[i].id })}
                    />
                </Panel>

                <Panel title="Safety Violations by Zone">
                    <Bars items={zoneViol.map((z) => ({ label: z.label, value: z.count, color: PALETTE.amber }))} onBar={() => navigate('safety')} />
                </Panel>

                <Panel title="Incident Severity Distribution">
                    <div>
                        <div style={{ display: 'flex', height: 22, borderRadius: 7, overflow: 'hidden', background: 'rgba(255,255,255,0.05)' }}>
                            {SEVERITIES.map((s) => {
                                const total = SEVERITIES.reduce((a, k) => a + (sevDist[k] as number), 0) || 1
                                const w = ((sevDist[s] as number) / total) * 100
                                return w > 0 ? <span key={s} title={`${severityLabel(s)}: ${sevDist[s]}`} style={{ width: `${w}%`, background: SEVERITY_COLOR[s] }} /> : null
                            })}
                        </div>
                        <div className="vicc-radar__legend" style={{ justifyContent: 'flex-start', marginTop: 10 }}>
                            {SEVERITIES.map((s) => (
                                <span key={s} className="vicc-legend-item"><span className="d" style={{ color: SEVERITY_COLOR[s], background: SEVERITY_COLOR[s] }} /> {severityLabel(s)} · {sevDist[s]}</span>
                            ))}
                        </div>
                    </div>
                </Panel>

                <Panel title="Top 5 High-Risk Zones (click → Safety)">
                    <Bars ranked items={riskZones.map((z) => ({ label: z.label, value: z.score, color: PALETTE.red }))} onBar={() => navigate('safety')} />
                </Panel>

                <Panel title="Detection Confidence Distribution">
                    <Histogram bins={confHist} />
                </Panel>

                <Panel title="Camera Availability (26 cameras)">
                    <Matrix cells={camCells} />
                    <div className="vicc-map__legend">
                        <span className="vicc-legend-item"><span className="d" style={{ color: PALETTE.vibrant, background: PALETTE.vibrant }} /> Online</span>
                        <span className="vicc-legend-item"><span className="d" style={{ color: PALETTE.amber, background: PALETTE.amber }} /> Degraded</span>
                        <span className="vicc-legend-item"><span className="d" style={{ color: '#6d8494', background: '#6d8494' }} /> Offline</span>
                    </div>
                </Panel>

                <Panel title="Average Alert Response Time">
                    <div style={{ display: 'flex', alignItems: 'baseline', gap: 10 }}>
                        <span style={{ fontSize: '1.8rem', fontWeight: 800 }}>{avgResp.toFixed(1)}</span>
                        <span style={{ color: 'var(--vc-muted)' }}>min avg · {respSeries.length} acknowledged</span>
                    </div>
                    <LineArea series={respSeries.length ? respSeries.slice(0, 12) : [0, 0]} color={PALETTE.cyan} height={96} />
                </Panel>

                <Panel title="Incident Resolution Trend">
                    <LineArea series={resolutionSeries} color={PALETTE.vibrant} fill="rgba(166,230,110,0.18)" height={120} />
                </Panel>

                <Panel title="Repeat Violations by Category">
                    <Bars items={repeats.map((r) => ({ label: r.label, value: r.count, color: r.color }))} onBar={() => navigate('safety')} />
                </Panel>
            </div>
        </div>
    )
}
